import React, { useState, useRef } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import ForensicLab from './components/ForensicLab';
import WarRoom from './components/WarRoom';
import { ScamAnalysis, IntelligenceLog, ForensicDossier } from './types';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: ScamAnalysis, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'intelligence' | 'warroom' | 'history'>('analyzer');
  const [liveMode, setLiveMode] = useState(false);
  const [activeAlert, setActiveAlert] = useState<any>(null);

  const currentSessionIdRef = useRef<string | null>(null);

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      const newLog: IntelligenceLog = {
        ...analysis,
        id: sessionId,
        originalMessage: message,
        timestamp: Date.now(),
        status: 'Open',
        linkedCaseIds: [],
        operationalRequests: [],
        governance: {
          privacyScore: 98,
          evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
          ethicsChecklist: { confirmed: true },
          legalStanding: 'Active Investigation',
          auditLog: []
        },
        messages: analysis.isScam ? (existingIdx >= 0 ? prev[existingIdx].messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
      };
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis, sessionId });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical') {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.safetyAlert,
        details: "AI Sovereign Agent engaged for target extraction.",
        isEngaging: true
      });
    }
  };

  const handleForensicFinalized = (dossier: ForensicDossier) => {
    if (!currentSessionIdRef.current) return;
    const sessionId = currentSessionIdRef.current;

    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, forensicReport: dossier } : l));
    setLatestAnalysis(prev => prev && prev.sessionId === sessionId ? { ...prev, analysis: { ...prev.analysis, forensicReport: dossier } } : prev);

    setActiveAlert({
      level: 'Low',
      message: "Forensic Case Finalized",
      details: "High-fidelity structured dossier extracted by Cyber Forensic Protocol.",
      isEngaging: false
    });
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {/* Sovereign Header */}
      <header className="glass-panel px-10 py-6 flex items-center justify-between sticky top-0 z-[60] border-b border-white/10">
        <div className="flex items-center space-x-6">
          <div className="bg-blue-600 p-3 rounded-2xl shadow-[0_0_25px_rgba(37,99,235,0.4)] glow-cobalt">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <div>
            <h1 className="text-2xl font-black tracking-tighter text-white uppercase">BHARAT CYBER <span className="text-blue-500">RAKSHAK</span></h1>
            <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.5em] font-mono">SOVEREIGN_AGENT_GRID_v2.5</p>
          </div>
        </div>

        <nav className="hidden md:flex items-center space-x-2 bg-white/5 p-1.5 rounded-2xl border border-white/10">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Containment" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Map" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="Sovereign War Room" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Dossiers" />
        </nav>

        <div className="flex items-center space-x-8">
           <div className="hidden lg:flex flex-col items-end">
              <span className="text-[9px] font-black uppercase text-slate-500 tracking-widest font-mono">Defense Node: DELHI_01</span>
              <span className="text-xs font-black text-green-500 uppercase flex items-center">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                ACTIVE_READY
              </span>
           </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'warroom' ? (
          <WarRoom />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : liveMode ? (
          <div className="max-w-4xl mx-auto">
             <button onClick={() => setLiveMode(false)} className="mb-8 text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center hover:text-white transition-colors">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                Exit Live Shield
             </button>
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
          </div>
        ) : (
          <div className="space-y-16 animate-in fade-in duration-1000">
            <div className="text-center space-y-8 py-10">
              <div className="inline-flex items-center px-6 py-2 rounded-full bg-blue-500/10 border border-blue-500/20 text-[11px] font-black text-blue-400 uppercase tracking-[0.4em] glow-cobalt">
                AUTONOMOUS FRAUD INTERCEPTION PROTOCOL
              </div>
              <h2 className="text-7xl md:text-8xl font-black text-white tracking-tighter leading-none uppercase">
                PROTECT THE <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-indigo-400 to-cyan-400">NATION</span>
              </h2>
              <p className="text-slate-400 max-w-3xl mx-auto text-xl font-medium leading-relaxed opacity-80">
                Cognitive agentic honey-pots. Multimodal synthesis. <br className="hidden md:block"/> Winning the war against cyber-fraud with Sovereign AI.
              </p>
              <div className="flex flex-col md:flex-row justify-center items-center gap-6 pt-8">
                <button onClick={() => setLiveMode(true)} className="group relative px-12 py-6 font-black text-white bg-blue-600 rounded-3xl glow-cobalt hover:bg-blue-500 transition-all hover:-translate-y-1 active:scale-95 overflow-hidden w-full md:w-auto">
                  <div className="relative flex items-center justify-center space-x-4">
                    <svg className="w-6 h-6 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                    <span className="text-lg uppercase tracking-[0.2em]">Deploy Live Shield</span>
                  </div>
                </button>
                <button onClick={() => setView('warroom')} className="px-12 py-6 font-black text-blue-400 bg-blue-500/10 border border-blue-500/20 rounded-3xl hover:bg-blue-500/20 transition-all w-full md:w-auto uppercase tracking-widest text-sm">
                  Enter War Room
                </button>
              </div>
            </div>

            <ScamAnalyzer onAnalysisComplete={handleAnalysisComplete} onAnalysisStart={() => {}} onClear={() => setLatestAnalysis(null)} />

            {latestAnalysis && (
              <div className="space-y-24 animate-in slide-in-from-bottom-20 duration-1000 pt-16 border-t border-white/5">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[900px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                      onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                      onForensicFinalized={handleForensicFinalized}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="py-16 px-12 border-t border-white/5 mt-32 bg-black/40 backdrop-blur-3xl">
         <div className="container mx-auto max-w-7xl flex flex-col md:flex-row items-center justify-between text-[11px] font-black uppercase tracking-[0.5em] text-slate-600 font-mono">
            <div className="flex items-center space-x-12">
               <div className="flex items-center space-x-3">
                 <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
                 <span className="text-slate-400">BCR_PROTOCOL_v2.5</span>
               </div>
               <span>Institutional Hub: BH-702</span>
            </div>
            <div className="mt-8 md:mt-0 space-x-12">
               <span className="text-blue-500">Forensic Integrity: 100%</span>
               <span>Audit Log: CRYPT-88</span>
            </div>
         </div>
      </footer>
    </div>
  );
};

