import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ScamRing, EmergingWave, ThreatPosture } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'rings' | 'waves' | 'governance'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);
    const potentialExposure = logs.filter(l => l.status === 'Open').reduce((sum, log) => sum + (log.potentialImpact || 0), 0);

    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20 || logs.some(l => l.threatLevel === 'Critical' && l.timestamp > Date.now() - 1800000)) {
      threatPosture = 'Red';
    } else if (recentLogs.length > 10) {
      threatPosture = 'Yellow';
    }

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const rings: Record<string, ScamRing> = {};
    logs.forEach(l => {
      const ringId = l.ringId || (l.linkedCaseIds?.length ? 'RING-C-01' : null);
      if (ringId) {
        if (!rings[ringId]) {
          rings[ringId] = { id: ringId, name: `Ring Cluster ${ringId.split('-').pop()}`, centralIdentifiers: [], caseCount: 0, totalPreventedInr: 0, riskTrend: 'Stable', isInternational: false };
        }
        rings[ringId].caseCount++;
        rings[ringId].totalPreventedInr += (l.estimatedImpact || 0);
        if (l.isInternational) rings[ringId].isInternational = true;
      }
    });

    const waves: Record<string, EmergingWave> = {};
    logs.filter(l => l.timestamp > Date.now() - 86400000).forEach(l => {
      if (!waves[l.scamType]) waves[l.scamType] = { pattern: l.scamType, firstSeen: l.timestamp, count: 0, velocity: 0, riskLevel: (l.threatLevel === 'Low' ? 'Medium' : l.threatLevel) as any };
      waves[l.scamType].count++;
    });

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: potentialExposure,
      threatPosture,
      topIdentifiers,
      emergingWaves: Object.values(waves).sort((a,b) => b.count - a.count),
      scamRings: Object.values(rings),
      channelDistribution: logs.reduce((acc: any, l) => { acc[l.channel] = (acc[l.channel] || 0) + 1; return acc; }, {}),
      languageDistribution: logs.reduce((acc: any, l) => { if (l.language) acc[l.language] = (acc[l.language] || 0) + 1; return acc; }, {}),
      honeypotSuccessRate: logs.filter(l => l.messages.length > 2).length ? (logs.filter(l => (Object.values(l.extractedInfo) as any[]).some(arr => arr.length > 0)).length / logs.filter(l => l.messages.length > 2).length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: logs.length ? logs.reduce((a,b)=>a+b.governance.privacyScore,0)/logs.length : 100,
        reviewPendingCount: logs.filter(l => l.governance.legalStanding === 'Probable Cause').length,
        complianceRate: logs.length ? (logs.filter(l => Object.values(l.governance.ethicsChecklist).every(v => v === true)).length / logs.length) * 100 : 100
      }
    };
  }, [logs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50 border-green-100',
    'Yellow': 'text-amber-600 bg-amber-50 border-amber-100',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
  }[analytics.threatPosture];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-8 rounded-[2rem] border shadow-2xl flex flex-col justify-center transition-all ${postureColor}`}>
           <div className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-60">National Threat Posture</div>
           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
           <div className="text-[9px] font-bold mt-2 opacity-40 uppercase tracking-widest font-mono">Defense Node DELHI_01</div>
        </div>
        <KPIBox title="Prevented Loss" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Nation-wide Interceptions" color="text-blue-600" />
        <KPIBox title="Shield Integrity" value={`${analytics.governanceMetrics.complianceRate.toFixed(1)}%`} sub="Institutional Compliance" color="text-indigo-600" />
        <KPIBox title="Success Rate" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Forensic Extraction" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Strategic Dashboard" />
        <TabNav active={activeTab === 'rings'} onClick={() => setActiveTab('rings')} label="Ring Intelligence" />
        <TabNav active={activeTab === 'waves'} onClick={() => setActiveTab('waves')} label="Emerging Patterns" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-10">
              <div className="flex justify-between items-center">
                 <div>
                    <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                       <div className="w-2.5 h-2.5 bg-blue-600 rounded-full mr-3 animate-pulse" />
                       Strategic Threat Map
                    </h3>
                    <p className="text-[11px] font-medium text-slate-400 mt-1">Simulating geographical origin clusters and cross-border vectors.</p>
                 </div>
                 <div className="flex items-center space-x-6 text-[10px] font-black uppercase tracking-widest text-slate-400">
                    <div className="flex items-center"><div className="w-2 h-2 bg-blue-500 rounded-full mr-2" /> Domestic</div>
                    <div className="flex items-center"><div className="w-2 h-2 bg-red-500 rounded-full mr-2" /> International</div>
                 </div>
              </div>

              <div className="aspect-video bg-slate-50 rounded-3xl border border-slate-100 relative overflow-hidden group">
                 <div className="absolute inset-0 opacity-5 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#1e293b 0.5px, transparent 0.5px)', backgroundSize: '24px 24px' }} />
                 {logs.filter(l => l.sourceIntelligence?.coordinates).slice(0, 50).map((log, i) => (
                    <div 
                      key={log.id} 
                      className="absolute group/blip cursor-pointer" 
                      style={{ 
                        top: `${15 + (log.sourceIntelligence?.coordinates?.lat || 0) % 70}%`, 
                        left: `${15 + (log.sourceIntelligence?.coordinates?.lng || 0) % 70}%` 
                      }}
                    >
                      <div className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-xl transition-all duration-300 group-hover/blip:scale-150 ${log.threatLevel === 'Critical' ? 'bg-red-500' : 'bg-blue-600'}`} />
                      <div className="hidden group-hover/blip:block absolute bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] font-black uppercase px-3 py-1.5 rounded-xl whitespace-nowrap z-30 shadow-2xl">
                        {log.scamType} ({log.sourceIntelligence?.likelyOrigin})
                      </div>
                    </div>
                 ))}
                 {logs.length === 0 && (
                    <div className="absolute inset-0 flex items-center justify-center opacity-20 italic text-xs font-black uppercase tracking-[0.4em] animate-pulse">
                       Synchronizing Defense Nodes...
                    </div>
                 )}
              </div>
           </div>

           <div className="lg:col-span-4 space-y-8">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-6">
                 <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                    <div className="w-2 h-2 bg-indigo-600 rounded-full mr-3" />
                    Top Repeat Identifiers
                 </h3>
                 <div className="space-y-3">
                    {analytics.topIdentifiers.length > 0 ? (
                       analytics.topIdentifiers.slice(0, 6).map((id, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl group hover:border-indigo-500/30 transition-all">
                             <div className="flex flex-col">
                                <span className="text-[8px] font-black text-indigo-600 uppercase mb-1 tracking-widest">{id.type} Handle</span>
                                <span className="text-[11px] font-mono font-bold text-slate-800">{id.value.substring(0, 12)}...</span>
                             </div>
                             <div className="flex flex-col items-end">
                                <span className="text-[10px] font-black text-slate-900">{id.count}</span>
                                <span className="text-[7px] font-black text-slate-400 uppercase tracking-tighter">Correlations</span>
                             </div>
                          </div>
                       ))
                    ) : (
                       <div className="py-20 text-center text-slate-300 italic text-[10px] font-black uppercase tracking-widest">Awaiting Network Data...</div>
                    )}
                 </div>
              </div>

              <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl space-y-6 relative overflow-hidden">
                 <div className="absolute top-0 right-0 w-24 h-24 bg-blue-600/10 blur-[50px] rounded-full" />
                 <h3 className="text-xs font-black text-blue-400 uppercase tracking-[0.4em]">Live Ticker Status</h3>
                 <div className="space-y-2">
                    <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-500">
                       <span>Processed</span>
                       <span>{logs.length} Cases</span>
                    </div>
                    <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                       <div className="h-full bg-blue-600 animate-pulse" style={{ width: `${Math.min(100, (logs.length / 500) * 100)}%` }} />
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'rings' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           {analytics.scamRings.length > 0 ? (
              analytics.scamRings.map(ring => (
