                        {line}
                      </div>
                    ))}
                 </div>
               </div>
             )}

             {!isActive && (
               <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-800 space-y-4">
                 <svg className="w-16 h-16 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
