          <WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} onOpenKey={handleKeySelect} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : view === 'multimedia' ? (
          <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
             <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-white/5 pb-10">
                <div className="space-y-2">
                   <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Multimedia Forensic Ops</h2>
                   <p className="text-slate-500 text-sm font-medium uppercase tracking-[0.2em]">Live Audio & Video Intelligence Stream</p>
                </div>
                <div className="flex items-center space-x-4 bg-blue-600/10 border border-blue-500/20 px-6 py-3 rounded-2xl">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-ping" />
