export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `INTERCEPTION DATA: "${message}"`,
    config: {
      responseMimeType: "application/json",
      systemInstruction: "You are a state-level cyber-crime forensic investigator. Detect scam intent, evaluate threat level, and extract all forensic indicators.",
      thinkingConfig: { thinkingBudget: 8000 }
    },
  });
  const analysis: ScamAnalysis = JSON.parse(response.text);
  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }
  return analysis;
};

export const generateSpeech = async (text: string, voice: string = 'Kore'): Promise<AudioBuffer> => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio synthesis failed");

  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  return await decodeAudioData(decodeBase64(base64Audio), audioCtx);
};

export const extractForensicDossier = async (conversation: string): Promise<ForensicDossier> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `FULL CONVERSATION LOG: \n${conversation}`,
    config: {
      responseMimeType: "application/json",
      systemInstruction: FORENSIC_OFFICER_DIRECTIVE,
      thinkingConfig: { thinkingBudget: 15000 }
    }
  });
  return JSON.parse(response.text);
};

export const generateAgenticBait = async (history: { role: string, content: string }[]): Promise<{ response: string, verdict: string, reasoning: string, strategyShift: string, suspicionLevel: number, greedLevel: number, assetRequired: string, extractedData: { upi: string[], bank: string[], phone: string[], links: string[] } }> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `CURRENT CONVERSATION LOG: ${JSON.stringify(history)}`,
    config: {
      responseMimeType: "application/json",
      systemInstruction: AGENT_PERSONA_DIRECTIVE,
      thinkingConfig: { thinkingBudget: 12000 }
    }
  });
  return JSON.parse(response.text);
};

export const generateSyntheticBaitImage = async (prompt: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: `Generate a photorealistic, non-existent person's ${prompt}. Ensure it looks like a standard identification document with blurred personal details but clear official markings. Synthetic only.` }]
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Image generation failed");
};

export const generateSyntheticBaitVideo = async (prompt: string): Promise<string> => {
  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: `A 5-second video of a person ${prompt}. Low lighting, looking slightly confused at a mobile phone screen, acting like they are trying to make a payment. Photorealistic but synthetic.`,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '9:16'
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({operation: operation});
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const analyzeVideoFrame = async (base64: string): Promise<VideoAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64 } },
        { text: "Examine frame for deepfake artifacts, unnatural lighting, or spoofed identification documents." }
      ],
    },
    config: {
      responseMimeType: "application/json"
    },
  });
  return JSON.parse(response.text);
};

export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage, generateSyntheticBaitImage, generateSyntheticBaitVideo, extractForensicDossier, generateSpeech } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics, BaitAsset, ForensicDossier } from '../types';
import { maskValue } from '../utils/masking';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onForensicFinalized?: (dossier: ForensicDossier) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onForensicFinalized, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [isGeneratingAsset, setIsGeneratingAsset] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [isSpeakingId, setIsSpeakingId] = useState<number | null>(null);
  const [psychState, setPsychState] = useState({ suspicion: 0, greed: 40 });
  const [activeStrategy, setActiveStrategy] = useState("Probing Identity");
  const [thinkingProcess, setThinkingProcess] = useState<string[]>([]);
  const [capturedIntel, setCapturedIntel] = useState<{value: string, type: string}[]>([]);
  const [sessionAssets, setSessionAssets] = useState<BaitAsset[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [initialMessages, isTyping, isGeneratingAsset]);

  const handleHearMessage = async (text: string, index: number) => {
    setIsSpeakingId(index);
    try {
      const buffer = await generateSpeech(`Say this in a worried Indian citizen voice: ${text}`, 'Puck');
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.onended = () => setIsSpeakingId(null);
      source.start();
    } catch (e) {
      console.error("Speech error", e);
      setIsSpeakingId(null);
    }
  };

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    setThinkingProcess(["Evaluating triggers...", "Analyzing response...", "Synthesizing..."]);

    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setPsychState({ suspicion: result.suspicionLevel, greed: result.greedLevel });
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      let attachedAsset: BaitAsset | undefined;

      if (result.assetRequired && result.assetRequired !== 'NONE') {
        setIsGeneratingAsset(true);
        try {
          const url = result.assetRequired === 'IDENTITY_CARD' 
            ? await generateSyntheticBaitImage("identification card")
            : await generateSyntheticBaitVideo("looking at phone");

          attachedAsset = {
            id: `ASSET-${Date.now()}`,
            type: result.assetRequired === 'IDENTITY_CARD' ? 'IMAGE' : 'VIDEO',
            url,
            purpose: `Synthetic ${result.assetRequired}`,
            timestamp: Date.now()
          };
          setSessionAssets(prev => [...prev, attachedAsset!]);
        } catch (e) {
          console.error(e);
        } finally {
          setIsGeneratingAsset(false);
        }
      }

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        verdict: result.verdict, // The SCAM|Score format
        reasoning: result.reasoning,
        strategyShift: result.strategyShift,
        attachedAsset,
        extractedData: result.extractedData
      }];

      onMessagesUpdate(updatedMessages);

    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
      setThinkingProcess([]);
    }
  };

  const handleFinalize = async () => {
    setIsFinalizing(true);
    try {
      const transcript = initialMessages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n');
      const dossier = await extractForensicDossier(transcript);
      onForensicFinalized?.(dossier);
    } catch (e) {
      console.error(e);
    } finally {
      setIsFinalizing(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    setTimeout(() => runAgenticTurn(updatedMessages), 1000);
  };

  return (
    <div className="glass-panel rounded-[3.5rem] border border-white/10 flex flex-col h-full overflow-hidden relative font-sans">
      {/* Top HUD */}
      <div className="p-8 bg-black/40 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl z-20">
        <div className="flex items-center space-x-6">
          <div className="w-14 h-14 rounded-2xl bg-blue-600/10 border border-blue-500/30 flex items-center justify-center">
             <div className="w-3 h-3 rounded-full bg-blue-500 shadow-[0_0_20px_#3b82f6] animate-pulse" />
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.4em] flex items-center">
              Autonomous Honey-Pot
              <span className="ml-4 text-[8px] font-black text-green-500 bg-green-500/10 px-2 py-0.5 rounded-full border border-green-500/20 uppercase">Agent_Active</span>
            </h3>
            <div className="mt-1 text-[9px] font-black uppercase tracking-widest text-slate-500 font-mono">
               Strategy: <span className="text-blue-400">{activeStrategy}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-12">
           <PsychMetric label="Suspicion" value={psychState.suspicion} color="bg-red-500" />
           <PsychMetric label="Greed" value={psychState.greed} color="bg-green-500" />
           <button 
             onClick={handleFinalize}
             disabled={isFinalizing || initialMessages.length < 3}
             className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all glow-cobalt"
           >
             {isFinalizing ? 'Finalizing...' : 'Finalize Case'}
           </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0f172a_0%,_#020617_100%)]">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-12 no-scrollbar">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'}`}>
                {m.verdict && (
                  <div className="mb-2 px-3 py-1 bg-slate-900 border border-white/10 rounded-full text-[9px] font-black text-blue-500 uppercase tracking-widest font-mono">
                    Operational Verdict: {m.verdict}
                  </div>
                )}

                <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-[15px] leading-relaxed relative group ${
                  m.role === 'scammer' ? 'bg-slate-900 text-slate-100 border border-white/10' : 'bg-blue-600 text-white shadow-2xl shadow-blue-900/40'
                }`}>
                  {m.content}
                  {m.role === 'bot' && (
                    <button 
                      onClick={() => handleHearMessage(m.content, idx)}
