import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ScamRing, EmergingWave, ThreatPosture } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'rings' | 'waves' | 'adaptive'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);
    const potentialExposure = logs.filter(l => l.status === 'Open').reduce((sum, log) => sum + (log.potentialImpact || 0), 0);

    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20 || logs.some(l => l.threatLevel === 'Critical' && l.timestamp > Date.now() - 1800000)) {
      threatPosture = 'Red';
    } else if (recentLogs.length > 10) {
      threatPosture = 'Yellow';
    }

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const rings: Record<string, ScamRing> = {};
    logs.forEach(l => {
      const ringId = l.ringId || (l.linkedCaseIds?.length ? 'RING-C-01' : null);
      if (ringId) {
        if (!rings[ringId]) {
          rings[ringId] = { id: ringId, name: `Ring Cluster ${ringId.split('-').pop()}`, centralIdentifiers: [], caseCount: 0, totalPreventedInr: 0, riskTrend: 'Stable', isInternational: false };
        }
        rings[ringId].caseCount++;
        rings[ringId].totalPreventedInr += (l.estimatedImpact || 0);
        if (l.isInternational) rings[ringId].isInternational = true;
      }
    });

    const waves: Record<string, EmergingWave> = {};
    logs.filter(l => l.timestamp > Date.now() - 86400000).forEach(l => {
      if (!waves[l.scamType]) waves[l.scamType] = { pattern: l.scamType, firstSeen: l.timestamp, count: 0, velocity: 0, riskLevel: (l.threatLevel === 'Low' ? 'Medium' : l.threatLevel) as any };
      waves[l.scamType].count++;
    });

    return {
