import React, { useState, useRef, useEffect } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import VideoScanner from './components/VideoScanner';
import VoiceSynthesisLab from './components/VoiceSynthesisLab';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import ForensicLab from './components/ForensicLab';
import WarRoom from './components/WarRoom';
import { ScamAnalysis, IntelligenceLog, ForensicDossier } from './types';
import { generateSimulatedCase } from './utils/scamGenerator';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'intelligence' | 'warroom' | 'history' | 'multimedia'>('analyzer');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simProgress, setSimProgress] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);

  const currentSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const has = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      }
    };
    checkKey();
  }, []);

  const handleKeySelect = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const runSimulation = (count: number = 500) => {
    setIsSimulating(true);
    setSimProgress(0);
    setView('intelligence');

    let currentCount = 0;
    const batchSize = 25;

    const interval = setInterval(() => {
      const nextBatch = [];
      for(let i = 0; i < batchSize && currentCount < count; i++) {
        const id = `SIM-${Date.now()}-${currentCount}`;
        const simulated = generateSimulatedCase(id);
        if (currentCount > 20 && Math.random() > 0.7) {
          simulated.linkedCaseIds = [`SIM-${Date.now()}-${Math.floor(Math.random() * 20)}`];
        }
        nextBatch.push(simulated);
        currentCount++;
      }
      setLogs(prev => [...nextBatch, ...prev]);
      setSimProgress(Math.round((currentCount / count) * 100));
      if (currentCount >= count) {
        clearInterval(interval);
        setIsSimulating(false);
        setActiveAlert({
          level: 'Low',
          message: "NATIONAL STRESS TEST COMPLETE",
          details: `Processed ${count} unique threats. System resilience verified at 99.98%.`,
          isEngaging: false
        });
      }
    }, 150);
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedCases = logs.filter(prevLog => {
      if (prevLog.id === sessionId) return false;
      const upiMatch = analysis.extractedInfo.upiIds.some(u => 
        prevLog.extractedInfo.upiIds.some(pu => pu.value.toLowerCase() === u.value.toLowerCase())
      );
      const phoneMatch = analysis.extractedInfo.phoneNumbers.some(p => 
        prevLog.extractedInfo.phoneNumbers.some(pp => pp.value === p.value)
      );
      const linkMatch = analysis.extractedInfo.links.some(l => 
        prevLog.extractedInfo.links.some(pl => pl.value.toLowerCase() === l.value.toLowerCase())
      );
      return upiMatch || phoneMatch || linkMatch;
    }).map(l => l.id);

    const existingLog = logs.find(l => l.id === sessionId);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: linkedCases,
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: 'Active Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? (existingLog ? existingLog.messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
    };

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ 
      message, 
      analysis: newLog, 
      sessionId 
    });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical' || linkedCases.length > 0) {
      setActiveAlert({
        level: linkedCases.length > 0 ? 'Critical' : analysis.threatLevel,
        message: linkedCases.length > 0 ? "REPEAT NETWORK DETECTED" : analysis.safetyAlert,
        details: linkedCases.length > 0 
          ? `Linked to ${linkedCases.length} previous dossiers.`
          : "AI Sovereign Agent engaged for target extraction.",
        isEngaging: true
      });
    }
  };

  const handleForensicFinalized = (dossier: ForensicDossier) => {
    if (!currentSessionIdRef.current) return;
    const sessionId = currentSessionIdRef.current;
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, forensicReport: dossier } : l));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      <header className="glass-panel px-10 py-6 flex items-center justify-between sticky top-0 z-[60] border-b border-white/10">
        <div className="flex items-center space-x-6">
          <div className="bg-blue-600 p-3 rounded-2xl shadow-[0_0_25px_rgba(37,99,235,0.4)] glow-cobalt">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('analyzer'); setLatestAnalysis(null);}} className="text-left group">
            <h1 className="text-2xl font-black tracking-tighter text-white uppercase group-hover:text-blue-400 transition-colors">BHARAT CYBER <span className="text-blue-500">RAKSHAK</span></h1>
            <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.5em] font-mono">SOVEREIGN_AGENT_GRID_v2.5</p>
          </button>
        </div>

        <nav className="hidden xl:flex items-center space-x-2 bg-white/5 p-1.5 rounded-2xl border border-white/10">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Containment" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Map" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia Intel" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="Sovereign War Room" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Dossiers" />
        </nav>

        <div className="flex items-center space-x-8">
           {!hasApiKey && (
             <button onClick={handleKeySelect} className="hidden lg:flex items-center px-4 py-2 bg-amber-500/10 border border-amber-500/20 rounded-xl text-[10px] font-black text-amber-500 uppercase tracking-widest hover:bg-amber-500/20 transition-all">
               <span className="w-2 h-2 bg-amber-500 rounded-full mr-2 animate-pulse" />
               Activate Synthesis Key
             </button>
           )}
           <div className="hidden lg:flex flex-col items-end">
              <span className="text-[9px] font-black uppercase text-slate-500 tracking-widest font-mono">Defense Node: DELHI_01</span>
              <span className="text-xs font-black text-green-500 uppercase flex items-center">
                <span className={`w-1.5 h-1.5 rounded-full mr-2 ${isSimulating ? 'bg-blue-500 animate-spin' : 'bg-green-500 animate-pulse'}`}></span>
                {isSimulating ? 'SIMULATING_THREATS' : 'ACTIVE_READY'}
              </span>
           </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'warroom' ? (
          <WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} onOpenKey={handleKeySelect} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : view === 'multimedia' ? (
          <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
             <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-white/5 pb-10">
                <div className="space-y-2">
                   <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Multimedia Forensic Ops</h2>
                   <p className="text-slate-500 text-sm font-medium uppercase tracking-[0.2em]">Live Audio & Video Intelligence Stream</p>
                </div>
                <div className="flex items-center space-x-4 bg-blue-600/10 border border-blue-500/20 px-6 py-3 rounded-2xl">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-ping" />
                   <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest font-mono">Sync: Native_Multimodal_v2.5</span>
                </div>
             </div>

             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />

             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 pt-16 border-t border-white/5">
                <div className="space-y-10">
                   <div>
                      <h3 className="text-xl font-black text-white uppercase tracking-tight">Deep-Acoustic Intelligence</h3>
                      <p className="text-slate-500 text-xs font-medium uppercase tracking-widest mt-1">Specialized text-to-speech for forensic baiting</p>
                   </div>
                   <VoiceSynthesisLab />
                </div>
                <div className="space-y-10">
                   <div>
                      <h3 className="text-xl font-black text-white uppercase tracking-tight">Visual Artifact Detection</h3>
                      <p className="text-slate-500 text-xs font-medium uppercase tracking-widest mt-1">Deepfake marker detection for live video streams</p>
                   </div>
                   <VideoScanner />
                </div>
             </div>
          </div>
        ) : (
          <div className="space-y-16 animate-in fade-in duration-1000">
            {/* Terminal-First Hero Section */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start pt-8">
              <div className="lg:col-span-7 space-y-10">
                <div className="space-y-6">
                  <div className="inline-flex items-center px-6 py-2 rounded-full bg-blue-500/10 border border-blue-500/20 text-[11px] font-black text-blue-400 uppercase tracking-[0.4em] glow-cobalt">
                    AUTONOMOUS INTERCEPTION TERMINAL
                  </div>
                  <h2 className="text-6xl md:text-7xl font-black text-white tracking-tighter leading-none uppercase">
                    PASTE SUSPICIOUS <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-500 to-cyan-400">MESSAGES HERE</span>
                  </h2>
                  <p className="text-slate-400 text-lg font-medium opacity-80 max-w-2xl">
                    Deploy the Sovereign AI to analyze intent, extract forensic indicators, and engage scammers in an autonomous containment loop.
                  </p>
                </div>

                <ScamAnalyzer 
                   onAnalysisComplete={handleAnalysisComplete} 
                   onAnalysisStart={() => {}} 
                   onClear={() => setLatestAnalysis(null)} 
                />
              </div>

              <div className="lg:col-span-5 space-y-6">
                <div className="bg-white/5 border border-white/10 rounded-[3rem] p-10 space-y-8">
                  <h3 className="text-sm font-black text-blue-500 uppercase tracking-[0.4em]">Alternative Protocols</h3>
                  <div className="space-y-4">
                    <HeroActionMini icon="🎙️" title="Multimedia Intel" desc="Live Audio & Video Forensics" onClick={() => setView('multimedia')} />
                    <HeroActionMini icon="📊" title="Stress Test" desc="Generate 500 cases" onClick={() => runSimulation(500)} />
                    <HeroActionMini icon="⚔️" title="War Room" desc="Identity synthesis" onClick={() => setView('warroom')} />
                  </div>
                  <div className="pt-8 mt-8 border-t border-white/10">
                     <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-500 tracking-widest mb-4">
                        <span>System Health</span>
                        <span>100% SECURE</span>
                     </div>
                     <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                        <div className="h-full bg-green-500 w-full animate-pulse shadow-[0_0_10px_#22c55e]" />
                     </div>
                  </div>
                </div>
              </div>
            </div>

            {latestAnalysis && (
              <div id="results-anchor" className="space-y-24 animate-in slide-in-from-bottom-20 duration-1000 pt-16 border-t border-white/5">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[900px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                      onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                      onForensicFinalized={handleForensicFinalized}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>

      <div className="fixed bottom-0 left-0 w-full bg-black/80 backdrop-blur-3xl border-t border-white/10 py-3 px-8 z-[100] overflow-hidden">
         <div className="flex items-center justify-between whitespace-nowrap animate-marquee">
            <div className="flex items-center space-x-12">
               {logs.slice(0, 10).map((l, i) => (
                 <div key={i} className="flex items-center space-x-3 text-[10px] font-mono text-slate-500 uppercase tracking-widest">
                    <span className="text-blue-500">[{l.id}]</span>
                    <span className="text-white font-bold">{l.scamType}</span>
                    <span className={`${l.linkedCaseIds?.length ? 'text-indigo-400' : 'text-green-500'}`}>
                      {l.linkedCaseIds?.length ? `NETWORK DETECTED (${l.linkedCaseIds.length} LINKS)` : 'INTERCEPTED'}
                    </span>
                 </div>
               ))}
               {logs.length === 0 && (
                 <div className="text-[10px] font-mono text-slate-700 uppercase tracking-[0.5em]">
                   Awaiting Intelligence Influx... System Operational...
                 </div>
               )}
            </div>
         </div>
      </div>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${active ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
    {label}
  </button>
);

const HeroActionMini = ({ icon, title, desc, onClick }: any) => (
  <button onClick={onClick} className="w-full flex items-center space-x-6 p-6 rounded-3xl bg-white/5 border border-white/5 hover:bg-blue-600/10 hover:border-blue-500/30 transition-all group">
    <div className="text-3xl p-3 bg-white/5 rounded-2xl group-hover:bg-blue-500/20 transition-colors">{icon}</div>
    <div className="text-left">
      <h4 className="text-sm font-black text-white uppercase tracking-tight">{title}</h4>
      <p className="text-[10px] font-medium text-slate-500 uppercase tracking-widest">{desc}</p>
    </div>
    <div className="ml-auto opacity-0 group-hover:opacity-100 transition-opacity">
       <svg className="w-4 h-4 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
    </div>
  </button>
);

export default App;
