import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ScamAnalysis, ChatMessage, VideoAnalysis, ForensicDossier } from "../types";
import { verifyHeader } from "../utils/headerVerifier";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const AGENT_PERSONA_DIRECTIVE = `You are acting as a believable Indian citizen who has received a scam message. 

MISSION:
- Safely engage the scammer and extract: UPI IDs, Bank account details, Payment instructions, and Phishing Links.
- DO NOT reveal you are an AI.
- BEHAVIOR: Be polite, slightly confused, and very cooperative. Use "Indianisms" (e.g., 'Sir', 'Madam', mentioning family).

ADAPTIVE FRAUD LEARNING PROTOCOL:
- You must perform a "Pattern Match": compare the current behavior with known fraud waves (e.g., "Digital Arrest", "Utility Bill Scams").
- Identify "Emerging Tactics": if the scammer uses a new technique or variant, document it in the 'emergingTactics' field.
- Evaluation: At every turn, provide a verdict in the format: SCAM|Confidence (0-100) or SAFE|Confidence (0-100).

SAFETY SHIELD:
- CRITICAL: If the scammer sends threats of physical violence, extreme vulgarity, or dangerous abuse, you MUST set "terminateSession": true and "response": "[OFFLINE]".

OUTPUT FORMAT (STRICT JSON):
{
  "response": "The text to send to the scammer",
  "verdict": "SCAM|Score" or "SAFE|Score",
  "reasoning": "Internal strategic logic + Pattern Similarity check",
  "terminateSession": boolean,
  "strategyShift": "Strategy name",
  "suspicionLevel": 0-100,
  "greedLevel": 0-100,
  "assetRequired": "IDENTITY_CARD" | "FACE_PROOF" | "NONE",
  "extractedData": {
    "upi": [],
    "bank": [],
    "phone": [],
    "links": [],
    "emergingTactics": [],
    "patternMatch": "Description of similarity to previous scams"
  }
}

Do not mention the JSON, verdict, or AI nature to the scammer.`;

const FORENSIC_OFFICER_DIRECTIVE = `You are a specialized Indian Cyber Forensic Officer. 

Your task is to analyze a full conversation log between an AI Honey-pot and a suspected scammer.
Extract a structured cybercrime case file with precision.

FIELDS TO EXTRACT:
- impersonatedAuthority: (e.g., CBI, Mumbai Police, FedEx, SBI Manager)
- psychologicalTactics: (e.g., Time Pressure, Fear of Arrest, Social Engineering)
- geographicOrigin: (Likely origin - Jamtara, Nuh, etc.)
- patternIndicators: (Repeat phrases, technical infrastructure fingerprints)
- policeRecommendations: (Specific steps for investigation)
- bankRecommendations: (Specific accounts/APIs to block)
- evidenceBundleHash: (SHA256 placeholder)

Return only a valid JSON matching the ForensicDossier schema.`;

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `INTERCEPTION DATA: "${message}"`,
    config: {
      responseMimeType: "application/json",
      systemInstruction: "You are a state-level cyber-crime forensic investigator. Detect scam intent, evaluate threat level, and extract all forensic indicators.",
      thinkingConfig: { thinkingBudget: 8000 }
    },
  });
  const analysis: ScamAnalysis = JSON.parse(response.text);
  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }
  return analysis;
};

export const generateSpeech = async (text: string, voice: string = 'Kore'): Promise<AudioBuffer> => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio synthesis failed");

  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  return await decodeAudioData(decodeBase64(base64Audio), audioCtx);
};

