<file path="components/BaitSession.tsx">
import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage, generateSyntheticBaitImage, generateSyntheticBaitVideo, extractForensicDossier, generateSpeech } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics, BaitAsset, ForensicDossier } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onForensicFinalized?: (dossier: ForensicDossier) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onForensicFinalized, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [isGeneratingAsset, setIsGeneratingAsset] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [isSpeakingId, setIsSpeakingId] = useState<number | null>(null);
  const [isTerminated, setIsTerminated] = useState(false);
  const [psychState, setPsychState] = useState({ suspicion: 0, greed: 40 });
  const [activeStrategy, setActiveStrategy] = useState("Adaptive Probing");
  const [thinkingProcess, setThinkingProcess] = useState<string[]>([]);
  const [sessionAssets, setSessionAssets] = useState<BaitAsset[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [initialMessages, isTyping, isGeneratingAsset]);

  const handleHearMessage = async (text: string, index: number) => {
    setIsSpeakingId(index);
    try {
      const buffer = await generateSpeech(`Say this in a worried Indian citizen voice: ${text}`, 'Puck');
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.onended = () => setIsSpeakingId(null);
      source.start();
    } catch (e) {
      console.error("Speech error", e);
      setIsSpeakingId(null);
    }
  };

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    if (isTerminated) return;
    setIsTyping(true);
    setThinkingProcess(["Context Pattern Matching...", "Adaptive Response Synthesis..."]);

    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      if (result.terminateSession) {
        setIsTerminated(true);
        const updatedMessages: ChatMessage[] = [...currentMessages, { 
          role: 'bot', 
          content: "[OFFLINE] - SESSION TERMINATED. Safety Shield triggered by non-compliant scammer behavior.", 
          timestamp: Date.now(),
          verdict: result.verdict,
          reasoning: "THREAT_DETECTED: Scammer breached safety protocols. Logging violation signature."
        }];
        onMessagesUpdate(updatedMessages);
        return;
      }

      setPsychState({ suspicion: result.suspicionLevel, greed: result.greedLevel });
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      let attachedAsset: BaitAsset | undefined;

      if (result.assetRequired && result.assetRequired !== 'NONE') {
        setIsGeneratingAsset(true);
        try {
          const url = result.assetRequired === 'IDENTITY_CARD' 
            ? await generateSyntheticBaitImage("identification card")
            : await generateSyntheticBaitVideo("looking at phone");

          attachedAsset = {
            id: `ASSET-${Date.now()}`,
            type: result.assetRequired === 'IDENTITY_CARD' ? 'IMAGE' : 'VIDEO',
            url,
            purpose: `Synthetic ${result.assetRequired}`,
            timestamp: Date.now()
          };
          setSessionAssets(prev => [...prev, attachedAsset!]);
        } catch (e) {
          console.error(e);
        } finally {
          setIsGeneratingAsset(false);
        }
      }

      const forensicData = {
        upi: result.extractedData.upi || [],
        bank: result.extractedData.bank || [],
        phone: result.extractedData.phone || [],
        links: result.extractedData.links || [],
        emergingTactics: result.extractedData.emergingTactics || [],
        patternMatch: result.extractedData.patternMatch || "Inference Pending"
      };

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        verdict: result.verdict,
        reasoning: result.reasoning,
        strategyShift: result.strategyShift,
        attachedAsset,
        extractedData: forensicData as any
      }];

      onMessagesUpdate(updatedMessages);

    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
      setThinkingProcess([]);
    }
  };

  const handleFinalize = async () => {
    setIsFinalizing(true);
    try {
      const transcript = initialMessages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n');
      const dossier = await extractForensicDossier(transcript);
      onForensicFinalized?.(dossier);
    } catch (e) {
      console.error(e);
    } finally {
      setIsFinalizing(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTerminated) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    setTimeout(() => runAgenticTurn(updatedMessages), 1000);
  };

  return (
    <div className="glass-panel rounded-[3.5rem] border border-white/10 flex flex-col h-full overflow-hidden relative font-sans shadow-2xl">
      {/* Top HUD */}
      <div className="p-8 bg-black/60 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl z-20">
        <div className="flex items-center space-x-6">
          <div className="w-14 h-14 rounded-2xl bg-blue-600/10 border border-blue-500/30 flex items-center justify-center">
             <div className={`w-3 h-3 rounded-full ${isTerminated ? 'bg-red-500 shadow-[0_0_20px_#ef4444]' : 'bg-blue-500 shadow-[0_0_20px_#3b82f6]'} animate-pulse`} />
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.4em] flex items-center">
              Adaptive Honey-Pot Agent
              <span className={`ml-4 text-[8px] font-black ${isTerminated ? 'text-red-500 bg-red-500/10' : 'text-green-500 bg-green-500/10'} px-2 py-0.5 rounded-full border border-green-500/20 uppercase tracking-widest`}>
                {isTerminated ? 'Protocol_Terminated' : 'Learning_Active'}
              </span>
            </h3>
            <div className="mt-1 text-[9px] font-black uppercase tracking-widest text-slate-500 font-mono">
               Active Strategy: <span className="text-blue-400">{activeStrategy}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-12">
           {!isTerminated && (
             <>
               <PsychMetric label="Target Suspicion" value={psychState.suspicion} color="bg-red-500" />
               <PsychMetric label="Target Greed" value={psychState.greed} color="bg-green-500" />
             </>
           )}
           <button 
             onClick={handleFinalize}
             disabled={isFinalizing || initialMessages.length < 3}
             className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all glow-cobalt"
           >
             {isFinalizing ? 'Finalizing...' : 'Finalize Dossier'}
           </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Chat Feed */}
        <div className="flex-1 flex flex-col overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0f172a_0%,_#020617_100%)]">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-12 no-scrollbar">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'} animate-in slide-in-from-bottom-4 duration-500`}>

                {/* Neural Confidence Gauge (Verdict) */}
                {m.verdict && (
                  <div className="mb-2 flex items-center space-x-2">
                    <span className={`text-[9px] font-black uppercase tracking-widest font-mono px-3 py-1 rounded-full border ${m.verdict.startsWith('SCAM') ? 'text-red-400 bg-red-400/10 border-red-400/20' : 'text-green-400 bg-green-400/10 border-green-400/20'}`}>
                      Adaptive Verdict: {m.verdict}
                    </span>
                    {m.verdict.startsWith('SCAM') && <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-ping" />}
                  </div>
                )}

                {/* Message Bubble */}
                <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-[15px] leading-relaxed relative group shadow-2xl ${
                  m.role === 'scammer' 
                  ? 'bg-slate-900 text-slate-100 border border-white/10 rounded-bl-none' 
                  : 'bg-blue-600 text-white border border-blue-400/30 rounded-br-none shadow-[0_10px_40px_rgba(37,99,235,0.2)]'
                }`}>
                  {m.content}
                  {m.role === 'bot' && !isTerminated && (
                    <button 
                      onClick={() => handleHearMessage(m.content, idx)}
                      className="absolute -left-12 top-1/2 -translate-y-1/2 p-2 hover:bg-blue-600 rounded-xl transition-all text-slate-500 hover:text-white"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                    </button>
                  )}
                </div>

                {/* Forensic JSON Ledger (Adaptive Insights) */}
                {m.extractedData && (
                  <div className="mt-6 w-full max-w-[85%] animate-in fade-in duration-1000">
                    <div className="flex items-center justify-between mb-2 text-[9px] font-black text-slate-500 uppercase tracking-widest px-4 font-mono">
                      <span>Neural Extraction Ledger</span>
                      <span className="text-blue-500 flex items-center">
                        <div className="w-1 h-1 bg-blue-500 rounded-full mr-2 animate-pulse" />
                        Adaptive Learning Sync
                      </span>
                    </div>
                    <pre className="bg-black/80 text-[11px] font-mono text-blue-300 p-8 rounded-[2.5rem] border border-white/5 overflow-x-auto shadow-inner leading-relaxed">
                      {JSON.stringify(m.extractedData, null, 2)}
                    </pre>
                  </div>
                )}
              </div>
            ))}

            {(isTyping || isGeneratingAsset) && !isTerminated && (
               <div className="flex flex-col items-end space-y-4 animate-pulse">
                  <div className="bg-blue-600/10 text-blue-400 px-8 py-4 rounded-full text-[10px] font-black uppercase tracking-[0.4em] border border-blue-500/20 font-mono">
                    {isGeneratingAsset ? 'Forging Forensic Asset...' : 'Adaptive Learning Active...'}
                  </div>
               </div>
            )}
          </div>

          {/* Input Terminal */}
          <div className="p-10 bg-black/80 border-t border-white/5 backdrop-blur-3xl">
            <form onSubmit={(e) => {
              e.preventDefault();
              const target = e.target as any;
              handleManualScammerReply(target.reply.value);
              target.reply.value = '';
            }} className="flex space-x-6">
              <input 
                name="reply"
                disabled={isTerminated}
                autoComplete="off"
                placeholder={isTerminated ? ">>> DEFENSE PROTOCOL ACTIVE - SESSION SEALED" : ">>> SIMULATE SCAMMER RESPONSE"}
                className={`flex-1 bg-white/5 border border-white/10 rounded-[2rem] px-8 py-5 text-sm text-white outline-none focus:ring-1 focus:ring-blue-600 font-mono transition-all ${isTerminated ? 'opacity-30 cursor-not-allowed' : 'focus:bg-white/10'}`}
              />
              <button 
                type="submit" 
                disabled={isTerminated}
                className={`bg-blue-600 px-10 rounded-[2rem] text-[11px] font-black uppercase tracking-widest transition-all glow-cobalt active:scale-95 ${isTerminated ? 'opacity-30 cursor-not-allowed' : 'hover:bg-blue-500'}`}
