import React from 'react';
import { KillChainStage } from '../types';

interface Props {
  currentStage: KillChainStage;
}

const stages: KillChainStage[] = ['Reconnaissance', 'Delivery', 'Exploitation', 'Actions on Objective'];

const KillChainVisualizer: React.FC<Props> = ({ currentStage }) => {
  const currentIndex = stages.indexOf(currentStage);

  return (
    <div className="bg-slate-950/50 rounded-2xl border border-white/10 p-6 space-y-4">
      <div className="flex justify-between items-center mb-2">
        <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.2em]">Cyber Kill Chain Mapping</h4>
        <span className="text-[9px] font-bold text-slate-500 font-mono">Status: {currentStage}</span>
      </div>
      <div className="relative flex justify-between items-center">
        {/* Connection Line */}
        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-white/10 -translate-y-1/2 z-0" />
        <div 
          className="absolute top-1/2 left-0 h-0.5 bg-blue-500 -translate-y-1/2 z-0 transition-all duration-1000" 
          style={{ width: `${(currentIndex / (stages.length - 1)) * 100}%` }} 
        />

        {stages.map((stage, idx) => {
          const isActive = idx <= currentIndex;
          const isCurrent = idx === currentIndex;
          return (
            <div key={stage} className="relative z-10 flex flex-col items-center">
              <div className={`w-4 h-4 rounded-full border-2 transition-all duration-500 ${
                isActive ? 'bg-blue-600 border-blue-400 shadow-[0_0_10px_blue]' : 'bg-slate-800 border-slate-700'
              } ${isCurrent ? 'scale-125 animate-pulse' : ''}`} />
              <span className={`mt-2 text-[8px] font-black uppercase tracking-tighter ${
                isActive ? 'text-blue-400' : 'text-slate-600'
              }`}>
                {stage.split(' ')[0]}
              </span>
            </div>
          );
        })}
      </div>
      <p className="text-[9px] text-slate-500 italic text-center pt-2">
        {currentIndex === 0 && "Threat is probing for vulnerabilities."}
        {currentIndex === 1 && "Scam vector is currently being transmitted to target."}
        {currentIndex === 2 && "Attacker is attempting to gain unauthorized access/info."}
        {currentIndex === 3 && "Scammer is executing financial siphoning or data theft."}
      </p>
    </div>
  );
};

export default KillChainVisualizer;
