           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
        </div>
        <KPIBox title="Shielded Assets" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Direct Prevention" color="text-blue-600" />
        <KPIBox title="Memory Store" value={analytics.scamLibrary.length} sub="Unique Signatures" color="text-indigo-600" />
        <KPIBox title="Success Rate" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Extraction Accuracy" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Strategic Map" />
        <TabNav active={activeTab === 'library'} onClick={() => setActiveTab('library')} label="Scam Memory Library" />
        <TabNav active={activeTab === 'adaptive'} onClick={() => setActiveTab('adaptive')} label="Adaptive Patterns" />
      </div>

      {activeTab === 'overview' && (
