               <div className="flex justify-between items-start mb-6">
                  <div className="text-[8px] font-black bg-blue-600 text-white px-2 py-1 rounded uppercase tracking-widest">SIGNATURE_ID: {s.id.split('-').pop()}</div>
                  <div className="text-[9px] font-bold text-slate-400 font-mono">{new Date(s.timestamp).toLocaleDateString()}</div>
