          ))}
          {analytics.scamLibrary.length === 0 && (
            <div className="col-span-full py-20 text-center opacity-20 text-xs font-black uppercase tracking-[0.4em]">Memory store initializing...</div>
          )}
        </div>
      )}

      {activeTab === 'adaptive' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
