      {activeTab === 'adaptive' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           <PatternCard title="Digital Arrest" level="Critical" desc="Similarity detected in 45% of Mumbai-origin calls. Mimics CBI/Police protocols." count={logs.filter(l => l.scamType.includes('Police')).length} />
