import React, { useState } from 'react';
import { generateSyntheticBaitImage } from '../services/geminiService';

interface Props {
  onRunSimulation?: (count: number) => void;
  hasKey?: boolean;
  onOpenKey?: () => void;
}

const WarRoom: React.FC<Props> = ({ onRunSimulation, hasKey, onOpenKey }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedId, setGeneratedId] = useState<string | null>(null);
  const [forgeLog, setForgeLog] = useState<string[]>(["SYSTEM_READY", "AWAITING_INPUT"]);

  const runForge = async (type: string) => {
    if (!hasKey) {
      onOpenKey?.();
      return;
    }
    setIsGenerating(true);
    setForgeLog(prev => [`INITIATING_${type}_SYNTHESIS`, ...prev]);
    try {
      const prompt = type === 'ID' 
        ? "high-security government identification card with blurred personal data, official hologram, Indian state emblem, synthetic person"
        : "official-looking bank statement from a major Indian bank, showing a large balance to attract scammers, blurred account numbers, high-fidelity";

      const url = await generateSyntheticBaitImage(prompt);
      setGeneratedId(url);
      setForgeLog(prev => [`${type}_SUCCESSFULLY_FORGED`, ...prev]);
    } catch (e) {
      setForgeLog(prev => [`SYNTHESIS_ERROR: ${e}`, ...prev]);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-700">
      {/* Left Panel: National Threat Grid */}
      <div className="lg:col-span-8 space-y-8">
        <div className="glass-panel rounded-[3rem] p-12 relative overflow-hidden h-[650px] border border-white/5">
          <div className="flex justify-between items-start mb-8 relative z-10">
            <div>
              <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.5em] mb-1">Command Hub</h3>
              <h2 className="text-4xl font-black text-white tracking-tighter uppercase">National Threat Matrix</h2>
              <p className="text-slate-500 text-xs font-medium max-w-md mt-2">Visualizing cross-institutional fraud vectors and cluster hotspots in real-time.</p>
            </div>
            <div className="flex flex-col items-end space-y-3">
              <button 
                onClick={() => onRunSimulation?.(500)}
                className="px-8 py-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all glow-cobalt active:scale-95"
              >
                Execute 500-Node Stress Test
              </button>
              <div className="flex items-center space-x-4 bg-black/40 px-4 py-2 rounded-xl border border-white/5">
                 <div className="flex items-center space-x-2">
                    <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-ping" />
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Active Links</span>
                 </div>
                 <div className="w-px h-3 bg-white/10" />
                 <span className="text-[10px] font-mono text-blue-500">BH-702_GRID</span>
              </div>
            </div>
          </div>

          <div className="relative h-full flex items-center justify-center opacity-40">
            {/* High-Fidelity India Map Silhouette */}
            <svg viewBox="0 0 800 900" className="h-[95%] w-auto text-blue-900 fill-current drop-shadow-[0_0_50px_rgba(37,99,235,0.2)]">
              <path d="M400,100 L450,150 L500,130 L550,200 L600,250 L580,350 L620,450 L550,550 L500,700 L450,850 L350,850 L300,750 L250,650 L200,550 L180,450 L220,350 L200,250 L250,150 Z" />
            </svg>

            <ThreatBlip top="25%" left="48%" color="bg-red-500" label="Ring: Delhi-NCR" />
            <ThreatBlip top="45%" left="38%" color="bg-orange-500" label="Hotspot: Jamtara-Link" />
            <ThreatBlip top="65%" left="52%" color="bg-blue-500" label="Hub: Kolkata-Transit" />
            <ThreatBlip top="35%" left="58%" color="bg-red-500" label="Critical: UP-West" />
            <ThreatBlip top="75%" left="45%" color="bg-green-500" label="Intercept: Bengaluru" />
          </div>

          <div className="absolute bottom-10 left-12 right-12 flex justify-between items-end z-20">
             <div className="flex space-x-8">
                <MiniStat label="Packets Filtered" value="2.4M" />
                <MiniStat label="AI Uptime" value="100%" />
             </div>
             <div className="text-[9px] font-mono text-slate-700 tracking-[0.4em] uppercase">Sovereign_Network_Defense</div>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-6">
          <StatCard label="Active Honeypots" value="1,248" trend="+12%" />
          <StatCard label="Prevented Siphoning" value="₹4.2M" trend="Safe" />
          <StatCard label="Sovereign Load" value="14.8%" trend="Optimal" />
        </div>
      </div>

      {/* Right Panel: Identity Forge & Sim Monitor */}
      <div className="lg:col-span-4 space-y-8">
        <div className="glass-panel rounded-[3rem] p-10 flex flex-col h-full border border-white/5">
          <header className="mb-8">
            <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.5em] mb-1">Forensic Lab</h3>
            <h2 className="text-2xl font-black text-white tracking-tight uppercase">Bait Identity Forge</h2>
            <p className="text-slate-500 text-[11px] mt-2 font-medium">Synthesizing high-fidelity assets to engage and extract scammer intelligence.</p>
          </header>

          <div className="flex-1 space-y-6">
            <div className="aspect-[3/4] rounded-[2.5rem] border border-white/5 bg-black/40 relative overflow-hidden flex items-center justify-center group">
              {generatedId ? (
                <img src={generatedId} className="w-full h-full object-cover animate-in fade-in zoom-in-95 duration-1000" alt="Synthetic Asset" />
              ) : (
                <div className="text-center space-y-6">
                  <div className={`w-20 h-20 rounded-3xl border-2 border-dashed border-white/10 mx-auto flex items-center justify-center transition-all ${isGenerating ? 'animate-spin border-blue-500 bg-blue-500/10' : ''}`}>
                    <svg className="w-10 h-10 text-white/10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v16m8-8H4" /></svg>
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Awaiting Synthesis Command</p>
                    {!hasKey && <p className="text-[9px] text-amber-500 font-bold uppercase mt-2">Institutional Key Required</p>}
                  </div>
                </div>
              )}
              {isGenerating && (
                <div className="absolute inset-0 bg-black/90 backdrop-blur-xl flex flex-col items-center justify-center space-y-4">
                  <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_blue]"></div>
                  <div className="text-center">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest block">Forging Synthetic Bait...</span>
                    <span className="text-[8px] font-mono text-slate-500 mt-2 block">LATENT_DIFFUSION_v4.2</span>
                  </div>
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 gap-4">
              <button 
                onClick={() => runForge('ID')}
                disabled={isGenerating}
                className={`py-5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${
                  hasKey ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-blue-600/20' : 'bg-amber-600 text-white'
                }`}
              >
                {hasKey ? 'Forge Identity Card' : 'Authorize Synthesis Key'}
              </button>
              <button 
                onClick={() => runForge('BANK')}
                disabled={isGenerating}
                className="py-5 bg-white/5 border border-white/10 hover:bg-white/10 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95"
              >
                Forge Bank Statement
              </button>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-white/5 h-40 overflow-y-auto no-scrollbar font-mono text-[9px] text-blue-400/80 space-y-2">
            {forgeLog.map((log, i) => (
              <div key={i} className="flex items-center space-x-2 animate-in slide-in-from-left-2">
                <span className="opacity-30">[{new Date().toLocaleTimeString()}]</span>
                <span className={log.includes('SUCCESS') ? 'text-green-500' : ''}>> {log}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const ThreatBlip = ({ top, left, color, label }: any) => (
  <div className="absolute group cursor-pointer" style={{ top, left }}>
    <div className={`w-4 h-4 rounded-full ${color} animate-ping absolute opacity-40`} />
    <div className={`w-4 h-4 rounded-full ${color} shadow-[0_0_20px_currentColor]`} />
    <div className="absolute top-6 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all duration-300 scale-90 group-hover:scale-100 bg-slate-900 border border-white/10 px-4 py-2 rounded-2xl whitespace-nowrap z-50 shadow-2xl">
      <span className="text-[10px] font-black text-white uppercase tracking-widest">{label}</span>
    </div>
  </div>
);

const MiniStat = ({ label, value }: any) => (
  <div className="space-y-1">
    <div className="text-[8px] font-black text-slate-600 uppercase tracking-widest">{label}</div>
    <div className="text-xs font-black text-white">{value}</div>
  </div>
);

const StatCard = ({ label, value, trend }: any) => (
  <div className="glass-panel rounded-[2rem] p-8 border border-white/5 flex flex-col justify-between hover:border-blue-500/30 transition-all cursor-default">
    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label}</span>
    <div className="mt-4 flex items-end justify-between">
      <span className="text-4xl font-black text-white tracking-tighter">{value}</span>
      <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg ${trend.includes('+') ? 'text-red-500 bg-red-500/10' : 'text-green-500 bg-green-500/10'}`}>{trend}</span>
    </div>
  </div>
);

export default WarRoom;

