import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ThreatPosture, ScamSignature } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'library' | 'adaptive'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);

    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20) threatPosture = 'Red';
    else if (recentLogs.length > 10) threatPosture = 'Yellow';

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const library: ScamSignature[] = logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
            ...l.extractedInfo.upiIds.map(u => u.value),
            ...l.extractedInfo.phoneNumbers.map(p => p.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Fear tactics", "Urgency"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.summary.split('.')[0],
          bank: l.sourceIntelligence?.institutionInference || "Multiple",
          method: l.channel.toUpperCase(),
          link: l.extractedInfo.links[0]?.value || "N/A",
          tactic: l.forensicReport?.psychologicalTactics[0] || "Social Engineering",
          timestamp: l.timestamp
        }
      }));

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: totalPrevention * 1.5,
      threatPosture,
      topIdentifiers,
      scamLibrary: library,
      honeypotSuccessRate: logs.filter(l => l.messages.length > 2).length ? (logs.filter(l => l.extractedInfo.upiIds.length > 0).length / logs.filter(l => l.messages.length > 2).length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: 98,
        complianceRate: 100
      }
    };
  }, [logs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50 border-green-100',
    'Yellow': 'text-amber-600 bg-amber-50 border-amber-100',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
