  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-8 rounded-[2rem] border shadow-2xl flex flex-col justify-center transition-all ${postureColor}`}>
           <div className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-60">National Defense Status</div>
           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
           <div className="mt-2 text-[9px] font-bold text-slate-500 uppercase tracking-widest font-mono">Status: Adaptive Learning Mode</div>
        </div>
        <KPIBox title="Shielded Assets" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Direct Prevention Value" color="text-blue-600" />
        <KPIBox title="Memory Store" value={analytics.scamLibrary.length} sub="Known Scam Patterns" color="text-indigo-600" />
        <KPIBox title="Extraction Depth" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Data Extraction Quality" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Strategic Matrix" />
        <TabNav active={activeTab === 'library'} onClick={() => setActiveTab('library')} label="Scam Memory Library" />
        <TabNav active={activeTab === 'adaptive'} onClick={() => setActiveTab('adaptive')} label="Trend Analysis" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-10">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                 <div className="w-2.5 h-2.5 bg-blue-600 rounded-full mr-3 animate-pulse" />
                 National Threat Intelligence Grid
