                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'library' && (
        <div className="space-y-8">
            <div className="bg-blue-600/5 border border-blue-100 p-8 rounded-3xl mb-8">
                <div className="flex items-center space-x-4 mb-4">
                    <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                    </div>
                    <div>
                        <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">Pattern Memory Store</h2>
                        <p className="text-xs text-slate-500 font-medium">Every trapped scam script is archived here for future similarity matching.</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {analytics.scamLibrary.map((s, i) => (
                    <div key={i} className="bg-white border border-slate-200 rounded-[2.5rem] shadow-2xl overflow-hidden hover:border-blue-500 transition-all flex flex-col group h-full">
                        <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex justify-between items-start">
