  clusterConfidence?: number;
  signalStrength: number; 
  headerStatus: HeaderStatus;
  sourceCategory: 'Telecom' | 'Social' | 'Web' | 'App' | 'Institutional';
  coordinates?: { lat: number, lng: number };
}

export type KillChainStage = 'Reconnaissance' | 'Delivery' | 'Exploitation' | 'Actions on Objective';

export interface ScamPattern {
  pattern: string;
  bank: string;
  method: string;
  link: string;
  tactic: string;
  timestamp: number;
}

export interface ScamSignature {
  id: string;
  type: string;
  firstMessage: string;
  extractedIndicators: string[];
  tactics: string[];
  timestamp: number;
  patternMeta: ScamPattern;
}

export interface ForensicDossier {
  impersonatedAuthority: string;
  psychologicalTactics: string[];
  geographicOrigin: string;
  patternIndicators: string[];
  policeRecommendations: string[];
  bankRecommendations: string[];
  evidenceBundleHash: string;
}

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number; 
  scamType: string;
  language?: string;
  channel: 'text' | 'call' | 'video' | 'audio' | 'qr' | 'app' | 'social' | 'screen-share';
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  safetyAlert: string;
  extractedInfo: ExtractedInfo;
  sourceIntelligence?: SourceIntelligence;
  killChainStage: KillChainStage;
  patternMatch?: {
    isSimilar: boolean;
    matchedSignatureId?: string;
    similarityScore: number;
    correlationLogic: string;
  };
  fingerprint: {
    primaryHandle: string;
    primaryPhone: string;
    primaryLink: string;
    category: string;
  };
  recommendedActions: string[];
  suggestedBaitResponse: string;
  potentialImpact?: number; 
  aiReasoningTrace?: string;
  forensicReport?: ForensicDossier;
  linkedCaseIds?: string[];
  multiPlatformPropagation?: boolean;
}

export interface ChatMessage {
  role: 'scammer' | 'bot';
