export default App;

import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ThreatPosture, ScamSignature } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'library' | 'adaptive'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);

    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20) threatPosture = 'Red';
    else if (recentLogs.length > 10) threatPosture = 'Yellow';

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const library: ScamSignature[] = logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
            ...l.extractedInfo.upiIds.map(u => u.value),
            ...l.extractedInfo.phoneNumbers.map(p => p.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.summary.split('.')[0] || "Unknown Message Pattern",
          bank: l.sourceIntelligence?.institutionInference || "Multiple/Generic",
          method: l.fingerprint.category || "Message",
          link: l.extractedInfo.links[0]?.value || "No Link Provided",
          tactic: l.forensicReport?.psychologicalTactics[0] || "Standard Phishing",
          timestamp: l.timestamp
        }
      }));

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: totalPrevention * 1.5,
      threatPosture,
      topIdentifiers,
      scamLibrary: library,
      honeypotSuccessRate: logs.filter(l => l.messages.length > 2).length ? (logs.filter(l => l.extractedInfo.upiIds.length > 0).length / logs.filter(l => l.messages.length > 2).length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: 98,
        complianceRate: 100
      }
    };
  }, [logs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50 border-green-100',
    'Yellow': 'text-amber-600 bg-amber-50 border-amber-100',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
  }[analytics.threatPosture];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-8 rounded-[2rem] border shadow-2xl flex flex-col justify-center transition-all ${postureColor}`}>
           <div className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-60">Sovereign Defense Nodes</div>
           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
           <div className="mt-2 text-[9px] font-bold text-slate-500 uppercase tracking-widest font-mono">Shielding: National Grid</div>
        </div>
        <KPIBox title="Shielded Assets" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Interception Value" color="text-blue-600" />
        <KPIBox title="Memory Store" value={analytics.scamLibrary.length} sub="Unique Scam Patterns" color="text-indigo-600" />
        <KPIBox title="Extraction Quality" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Data Siphoning Rate" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Tactical Grid" />
        <TabNav active={activeTab === 'library'} onClick={() => setActiveTab('library')} label="Scam Memory Store" />
        <TabNav active={activeTab === 'adaptive'} onClick={() => setActiveTab('adaptive')} label="Pattern Trends" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-10">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                 <div className="w-2.5 h-2.5 bg-blue-600 rounded-full mr-3 animate-pulse" />
                 Global Threat Hotspots
              </h3>
              <div className="aspect-video bg-slate-50 rounded-3xl border border-slate-100 relative overflow-hidden group">
                 <div className="absolute inset-0 opacity-5 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#1e293b 0.5px, transparent 0.5px)', backgroundSize: '24px 24px' }} />
                 {logs.filter(l => l.sourceIntelligence?.coordinates).slice(0, 50).map((log) => (
                    <div 
                      key={log.id} 
                      className="absolute group/blip cursor-pointer" 
                      style={{ 
                        top: `${15 + (log.sourceIntelligence?.coordinates?.lat || 0) % 70}%`, 
                        left: `${15 + (log.sourceIntelligence?.coordinates?.lng || 0) % 70}%` 
                      }}
                    >
                      <div className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-xl ${log.threatLevel === 'Critical' ? 'bg-red-500' : 'bg-blue-600'}`} />
                    </div>
                 ))}
              </div>
           </div>
           <div className="lg:col-span-4 bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center mb-8">
                 <div className="w-2 h-2 bg-indigo-600 rounded-full mr-3" />
                 Indicator Persistence
              </h3>
              <div className="space-y-3">
                 {analytics.topIdentifiers.slice(0, 6).map((id, i) => (
                   <div key={i} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                      <div className="flex flex-col">
                         <span className="text-[8px] font-black text-indigo-600 uppercase mb-1 tracking-widest">{id.type}</span>
                         <span className="text-[11px] font-mono font-bold text-slate-800 truncate max-w-[120px]">{id.value}</span>
                      </div>
                      <div className="text-[10px] font-black text-slate-900">{id.count} Hits</div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'library' && (
        <div className="space-y-8">
            <div className="bg-blue-600/5 border border-blue-100 p-8 rounded-3xl">
                <div className="flex items-center space-x-4 mb-4">
                    <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl">
                        <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sovereign Memory Library</h2>
                        <p className="text-sm text-slate-500 font-medium">Categorized repository of every trapped scam script, bank target, and malicious method.</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {analytics.scamLibrary.map((s, i) => (
                    <div key={i} className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden hover:border-blue-500 transition-all flex flex-col group h-full hover:scale-[1.01] duration-500">
                        <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                            <div className="space-y-1">
                                <div className="text-[9px] font-black text-blue-600 uppercase tracking-[0.2em]">{s.type}</div>
                                <div className="text-xs font-black text-slate-900 uppercase font-mono">SIGNATURE_REF: {s.id.split('-').pop()}</div>
                            </div>
                            <div className="text-right">
                                <div className="text-[10px] font-bold text-slate-400 font-mono">{new Date(s.timestamp).toLocaleDateString()}</div>
                                <div className="text-[10px] font-bold text-slate-400 font-mono">{new Date(s.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                            </div>
                        </div>

                        <div className="p-8 flex-1 space-y-8">
                            <div className="space-y-4">
                                <div className="flex items-center justify-between">
                                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                                        <div className="w-1.5 h-1.5 bg-blue-500 rounded-full mr-2" />
                                        Pattern ID
                                    </h4>
                                    <span className="text-[9px] font-black text-indigo-500 bg-indigo-50 px-2 py-1 rounded">TRAPPED_TRIPWIRE</span>
                                </div>
                                <p className="text-[13px] text-slate-700 leading-relaxed font-bold italic bg-slate-50 p-5 rounded-3xl border border-slate-100 border-l-4 border-l-blue-600">
                                    "{s.patternMeta.pattern}"
                                </p>
                            </div>

                            <div className="grid grid-cols-2 gap-8">
                                <div className="space-y-3">
                                    <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Bank Nexus</h4>
                                    <div className="text-sm font-black text-slate-900 uppercase tracking-tight">{s.patternMeta.bank}</div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Method Vector</h4>
                                    <div className="text-sm font-black text-blue-600 uppercase tracking-tight">{s.patternMeta.method}</div>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center justify-between">
                                    <span>Script Analysis (Tactics)</span>
                                    <svg className="w-4 h-4 text-slate-200" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                </h4>
                                <div className="flex flex-wrap gap-2">
                                    {s.tactics.map((t, ti) => (
                                        <span key={ti} className="text-[9px] font-black text-slate-600 bg-slate-100 border border-slate-200 px-3 py-1.5 rounded-xl uppercase">
                                            {t}
                                        </span>
                                    ))}
                                </div>
                            </div>

                            <div className="space-y-4">
                                <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Malicious Link (Extracted)</h4>
                                <div className="p-4 bg-slate-950 rounded-2xl border border-white/5 font-mono text-[10px] text-blue-400 truncate shadow-inner">
                                    {s.patternMeta.link}
                                </div>
                            </div>
                        </div>

                        <div className="p-8 bg-slate-900 text-white flex items-center justify-between group-hover:bg-blue-600 transition-colors">
                            <div className="flex items-center space-x-3">
                                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                                <span className="text-[10px] font-black uppercase tracking-[0.3em]">Integrity Verified</span>
                            </div>
                            <button className="text-[10px] font-black uppercase tracking-widest hover:underline">View Forensic Data →</button>
                        </div>
                    </div>
                ))}

                {analytics.scamLibrary.length === 0 && (
                    <div className="col-span-full py-40 text-center flex flex-col items-center justify-center space-y-8 opacity-40">
                        <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center border-4 border-dashed border-slate-200">
                            <svg className="w-16 h-16 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 8v4l3 2m6-2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <div className="space-y-3">
                            <p className="text-xl font-black uppercase text-slate-500 tracking-[0.4em]">Memory Library Initializing</p>
                            <p className="text-sm text-slate-400 font-medium max-w-md">The sovereign store will populate automatically as scams are intercepted and analyzed by the defense grid.</p>
                        </div>
                    </div>
                )}
            </div>
        </div>
      )}

      {activeTab === 'adaptive' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           <PatternCard title="Digital Arrest Loop" level="Critical" desc="Scammers use Mumbai Police video-call bait to extort professional data." count={logs.filter(l => l.scamType.includes('Police')).length} />
           <PatternCard title="Part-time Job Trap" level="High" desc="Luring fresh graduates with daily payout tasks before exit-scamming higher deposits." count={logs.filter(l => l.scamType.includes('Job')).length} />
           <PatternCard title="Electricity Bill Rush" level="Medium" desc="High-volume bulk SMS targeting urban residents during bill cycle peaks." count={logs.filter(l => l.scamType.includes('Utility')).length} />
        </div>
      )}
    </div>
  );
};

const PatternCard = ({ title, level, desc, count }: any) => (
  <div className="bg-white border border-slate-200 p-10 rounded-[3.5rem] shadow-2xl space-y-8 hover:border-blue-500 transition-all cursor-pointer group hover:scale-[1.02] duration-500">
    <div className="flex justify-between items-start">
      <div className="space-y-2">
        <h4 className="text-xl font-black text-slate-900 uppercase tracking-tight">{title}</h4>
        <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${level === 'Critical' ? 'bg-red-600 text-white shadow-[0_6px_15px_rgba(220,38,38,0.2)]' : 'bg-blue-600 text-white shadow-[0_6px_15px_rgba(37,99,235,0.2)]'}`}>{level} Risk</span>
      </div>
      <div className="text-3xl font-black text-slate-200 group-hover:text-blue-100 transition-colors">#{count}</div>
    </div>
    <p className="text-sm text-slate-500 leading-relaxed font-medium">{desc}</p>
    <div className="pt-4 flex items-center space-x-3 text-[11px] font-black text-blue-600 uppercase tracking-widest group-hover:translate-x-2 transition-transform">
      <span>Analyze Cluster Logic</span>
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
    </div>
  </div>
);

const KPIBox = ({ title, value, sub, color }: any) => (
  <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-2xl transition-all hover:scale-[1.03] group cursor-default">
    <div className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3">{title}</div>
    <div className={`text-5xl font-black ${color} tracking-tighter`}>{value}</div>
    <div className="text-[10px] font-bold text-slate-400 uppercase mt-4 tracking-widest">{sub}</div>
  </div>
);

const TabNav = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-10 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${active ? 'bg-white text-slate-900 shadow-2xl border border-slate-100 ring-4 ring-blue-50' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>
    {label}
  </button>
);

export default IntelligenceDashboard;

export interface ExtractedItem<T> {
  value: T;
  confidence: number; 
  timestamp: number;
}

export interface ExtractedInfo {
  upiIds: ExtractedItem<string>[];
  bankDetails: ExtractedItem<string>[];
  ifscCodes: ExtractedItem<string>[];
  phoneNumbers: ExtractedItem<string>[];
  links: ExtractedItem<string>[];
  cryptoWallets: ExtractedItem<string>[];
  fakeIdentities: ExtractedItem<string>[];
}

export type HeaderStatus = 'VERIFIED_INSTITUTION' | 'SPOOFED_HEADER' | 'UNKNOWN_SENDER' | 'NOT_APPLICABLE';
export type ThreatPosture = 'Green' | 'Yellow' | 'Red';

export interface BaitAsset {
  id: string;
  type: 'IMAGE' | 'VIDEO' | 'AUDIO';
  url: string;
  purpose: string;
  timestamp: number;
}

export interface SourceIntelligence {
  likelyOrigin: string; 
  networkDetails: string; 
  institutionInference: string; 
  isCrossBorder: boolean;
  geographicMarkers: string[];
  clusterId?: string; 
  clusterConfidence?: number;
  signalStrength: number; 
  headerStatus: HeaderStatus;
  sourceCategory: 'Telecom' | 'Social' | 'Web' | 'App' | 'Institutional';
  coordinates?: { lat: number, lng: number };
}

export type KillChainStage = 'Reconnaissance' | 'Delivery' | 'Exploitation' | 'Actions on Objective';

export interface ScamPattern {
  pattern: string;
  bank: string;
  method: string;
  link: string;
}

export interface ScamSignature {
  id: string;
  type: string;
  firstMessage: string;
  extractedIndicators: string[];
  tactics: string[];
  timestamp: number;
  patternMeta: ScamPattern;
}

export interface ForensicDossier {
  impersonatedAuthority: string;
  psychologicalTactics: string[];
  geographicOrigin: string;
  patternIndicators: string[];
  policeRecommendations: string[];
  bankRecommendations: string[];
  evidenceBundleHash: string;
}

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number; 
  scamType: string;
  language?: string;
  channel: 'text' | 'call' | 'video' | 'audio' | 'qr' | 'app' | 'social' | 'screen-share';
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  safetyAlert: string;
  extractedInfo: ExtractedInfo;
  sourceIntelligence?: SourceIntelligence;
  killChainStage: KillChainStage;
  patternMatch?: {
    isSimilar: boolean;
    matchedSignatureId?: string;
    similarityScore: number;
    correlationLogic: string;
  };
  fingerprint: {
    primaryHandle: string;
    primaryPhone: string;
    primaryLink: string;
    category: string;
  };
  recommendedActions: string[];
  suggestedBaitResponse: string;
  potentialImpact?: number; 
  aiReasoningTrace?: string;
  forensicReport?: ForensicDossier;
  linkedCaseIds?: string[];
  multiPlatformPropagation?: boolean;
}

export interface ChatMessage {
  role: 'scammer' | 'bot';
  content: string;
  timestamp: number;
  verdict?: string; 
  reasoning?: string; 
  strategyShift?: string; 
  persona?: string; 
  psychState?: { greed: number, suspicion: number };
  attachedAsset?: BaitAsset;
  extractedData?: {
    upi: string[];
    bank: string[];
    phone: string[];
    links: string[];
    patternMatch?: string;
  };
}

export interface IntelligenceLog extends ScamAnalysis {
  id: string;
  originalMessage: string;
  timestamp: number;
  messages: ChatMessage[]; 
  status: 'Open' | 'Investigating' | 'Blocked' | 'Resolved';
  linkedCaseIds: string[];
  ringId?: string;
  governance: GovernanceDossier;
  operationalRequests: OperationalRequest[];
  isInternational?: boolean;
  estimatedImpact?: number;
}

export interface VideoAnalysis {
  isFraudulent: boolean;
  subjectIdentification: string;
  detectedThreats: string[];
  forensicNotes: string;
}

export interface EngagementMetrics {
  extractionCount: number;
  durationMs: number;
  messageCount: number;
  scammerEngagementLevel: number;
}

export interface AnalyticsSummary {
  totalPreventionInr: number;
  potentialExposureInr: number;
  threatPosture: ThreatPosture;
  topIdentifiers: { value: string, type: string, count: number }[];
  scamLibrary: ScamSignature[];
  honeypotSuccessRate: number;
  governanceMetrics: {
    avgPrivacyScore: number;
    complianceRate: number;
  };
}

export interface OperationalRequest {
  id: string;
  type: string;
  target: string;
  status: 'Pending' | 'Sent' | 'Executed';
  priority: 'Low' | 'Medium' | 'High' | 'Urgent';
}

export interface GovernanceDossier {
  privacyScore: number;
  evidenceIntegrityHash: string;
  ethicsChecklist: Record<string, boolean>;
  legalStanding: string;
  auditLog: { action: string; timestamp: number; actor: string }[];
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import VideoScanner from './components/VideoScanner';
import VoiceSynthesisLab from './components/VoiceSynthesisLab';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import ForensicLab from './components/ForensicLab';
import WarRoom from './components/WarRoom';
import { ScamAnalysis, IntelligenceLog, ForensicDossier, ScamSignature } from './types';
import { generateSimulatedCase } from './utils/scamGenerator';
import { analyzeMessage } from './services/geminiService';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'intelligence' | 'warroom' | 'history' | 'multimedia'>('analyzer');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simProgress, setSimProgress] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);

  // Optimized Scam Memory Store mapping to match User's JSON structure
  const scamLibrary = useMemo((): ScamSignature[] => {
    return logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
          ...l.extractedInfo.upiIds.map(u => u.value),
          ...l.extractedInfo.phoneNumbers.map(p => p.value),
          ...l.extractedInfo.links.map(link => link.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 50 ? l.originalMessage.substring(0, 50) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Generic",
          method: l.channel.toUpperCase(),
          link: l.extractedInfo.links[0]?.value || "N/A"
        }
      }));
  }, [logs]);

  const currentSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const has = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      }
    };
    checkKey();
  }, []);

  const handleKeySelect = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const runSimulation = (count: number = 500) => {
    setIsSimulating(true);
    setSimProgress(0);
    setView('intelligence');
    let currentCount = 0;
    const batchSize = 25;
    const interval = setInterval(() => {
      const nextBatch = [];
      for(let i = 0; i < batchSize && currentCount < count; i++) {
        const id = `SIM-${Date.now()}-${currentCount}`;
        const simulated = generateSimulatedCase(id);
        nextBatch.push(simulated);
        currentCount++;
      }
      setLogs(prev => [...nextBatch, ...prev]);
      setSimProgress(Math.round((currentCount / count) * 100));
      if (currentCount >= count) {
        clearInterval(interval);
        setIsSimulating(false);
      }
    }, 150);
  };

  const handleManualAnalyze = async (message: string) => {
    const analysisResult = await analyzeMessage(message, scamLibrary);
    handleAnalysisComplete(message, analysisResult, true);
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedCases = logs.filter(prevLog => {
      if (prevLog.id === sessionId) return false;
      const upiMatch = analysis.extractedInfo.upiIds.some(u => 
        prevLog.extractedInfo.upiIds.some(pu => pu.value.toLowerCase() === u.value.toLowerCase())
      );
      const linkMatch = analysis.extractedInfo.links.some(l => 
        prevLog.extractedInfo.links.some(pl => pl.value === l.value)
      );
      return upiMatch || linkMatch;
    }).map(l => l.id);

    const existingLog = logs.find(l => l.id === sessionId);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: linkedCases,
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: 'Active Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? (existingLog ? existingLog.messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
    };

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical' || linkedCases.length > 0 || analysis.patternMatch?.isSimilar) {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.patternMatch?.isSimilar ? "HISTORICAL PATTERN DETECTED" : analysis.safetyAlert,
        details: analysis.patternMatch?.correlationLogic || "Deploying Sovereign Agent for extraction.",
        isEngaging: true
      });
    }
  };

  const handleForensicFinalized = (dossier: ForensicDossier) => {
    if (!currentSessionIdRef.current) return;
    const sessionId = currentSessionIdRef.current;
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, forensicReport: dossier } : l));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      <header className="glass-panel px-10 py-6 flex items-center justify-between sticky top-0 z-[60] border-b border-white/10">
        <div className="flex items-center space-x-6">
          <div className="bg-blue-600 p-3 rounded-2xl shadow-[0_0_25px_rgba(37,99,235,0.4)] glow-cobalt">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('analyzer'); setLatestAnalysis(null);}} className="text-left group">
            <h1 className="text-2xl font-black tracking-tighter text-white uppercase group-hover:text-blue-400 transition-colors">BHARAT CYBER <span className="text-blue-500">RAKSHAK</span></h1>
            <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.5em] font-mono">SOVEREIGN_AGENT_GRID_v2.5</p>
          </button>
        </div>

        <nav className="hidden xl:flex items-center space-x-2 bg-white/5 p-1.5 rounded-2xl border border-white/10">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Containment" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Map" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia Intel" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="Sovereign War Room" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Dossiers" />
        </nav>

        <div className="flex items-center space-x-8">
           <div className="hidden lg:flex flex-col items-end">
              <span className="text-[9px] font-black uppercase text-slate-500 tracking-widest font-mono">Memory Store</span>
              <span className="text-xs font-black text-blue-500 uppercase flex items-center">
                <span className={`w-1.5 h-1.5 rounded-full mr-2 bg-blue-500 animate-pulse`}></span>
                {scamLibrary.length} PATTERNS
              </span>
           </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'warroom' ? (
          <WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} onOpenKey={handleKeySelect} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : view === 'multimedia' ? (
          <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <VoiceSynthesisLab />
                <VideoScanner />
             </div>
          </div>
        ) : (
          <div className="space-y-16">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start pt-8">
              <div className="lg:col-span-7 space-y-10">
                <h2 className="text-6xl font-black text-white tracking-tighter uppercase leading-none">
                  ADAPTIVE <span className="text-blue-500">DEFENSE</span> INTERFACE
                </h2>
                <ScamAnalyzer 
                   onAnalysisComplete={(msg) => handleManualAnalyze(msg)} 
                   onAnalysisStart={() => {}} 
                   onClear={() => setLatestAnalysis(null)} 
                />
              </div>
              <div className="lg:col-span-5 space-y-6">
                <div className="bg-white/5 border border-white/10 rounded-[3rem] p-10 space-y-8">
                  <h3 className="text-sm font-black text-blue-500 uppercase tracking-[0.4em]">Adaptive Learning Stats</h3>
                  <div className="grid grid-cols-2 gap-4">
                     <MemoryStat label="Archived Patterns" value={scamLibrary.length} />
                     <MemoryStat label="Trapped Identifiers" value={scamLibrary.reduce((acc, s) => acc + s.extractedIndicators.length, 0)} />
                  </div>
                  <div className="pt-6 border-t border-white/10">
                    <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic">
                        "System maintains an internal 'scam_memory.json' context for high-fidelity pattern matching."
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {latestAnalysis && (
              <div id="results-anchor" className="space-y-24 animate-in slide-in-from-bottom-20 duration-1000 pt-16 border-t border-white/5">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[900px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                      onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                      onForensicFinalized={handleForensicFinalized}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${active ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
