export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  const pastScamsContext = historySignatures.length > 0 
    ? historySignatures.map(s => `Pattern: ${s.patternMeta.pattern} | Tactics: ${s.tactics.join(', ')}`).join('\n')
    : "No previous records.";

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `SYSTEM_PROTOCOL:
    You have access to a growing memory of previously confirmed scam messages.

    THESE ARE EXAMPLES OF REAL SCAM PATTERNS SEEN BEFORE:
    ${pastScamsContext}

    When you analyze a new message, you must not only look for keywords, but also compare its style, intent, and structure with the past scam patterns.
    If the new message is similar in behavior, tone, or strategy to any past scam, you must classify it as SCAM even if the exact words are different.
    Your goal is to detect new and evolving scams based on learned patterns.

    NEW_MESSAGE_FOR_ANALYSIS: "${message}"`,
    config: {
      responseMimeType: "application/json",
      systemInstruction: "You are a state-level cyber-crime forensic investigator. Detect scam intent, evaluate threat level, and perform a Similarity Check against known signatures. Ask: 'Is this similar to scams we’ve seen before?'",
      thinkingConfig: { thinkingBudget: 8000 }
    },
  });

  const analysis: ScamAnalysis = JSON.parse(response.text);
  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }
  return analysis;
};

export const generateAgenticBait = async (history: { role: string, content: string }[], memoryStore: ScamSignature[] = []): Promise<any> => {
