    if (!reply.trim() || isTerminated) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);
    setTimeout(() => runAgenticTurn(updatedMessages), 1000);
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  return (
    <div className="glass-panel rounded-[3.5rem] border border-white/10 flex flex-col h-full overflow-hidden relative font-sans shadow-2xl">
      <div className="p-8 bg-black/60 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl z-20">
        <div className="flex items-center space-x-6">
          <div className="w-14 h-14 rounded-2xl bg-blue-600/10 border border-blue-500/30 flex items-center justify-center">
             <div className={`w-3 h-3 rounded-full ${isTerminated ? 'bg-red-500 shadow-[0_0_20px_#ef4444]' : 'bg-blue-500 shadow-[0_0_20px_#3b82f6]'} animate-pulse`} />
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.4em] flex items-center">
              Adaptive Honey-Pot Agent
              <span className={`ml-4 text-[8px] font-black ${isTerminated ? 'text-red-500 bg-red-500/10' : 'text-green-500 bg-green-500/10'} px-2 py-0.5 rounded-full border border-green-500/20 uppercase tracking-widest`}>
                {isTerminated ? 'Protocol_Terminated' : 'Learning_Active'}
              </span>
            </h3>
            <div className="mt-1 text-[9px] font-black uppercase tracking-widest text-slate-500 font-mono">
               Active Strategy: <span className="text-blue-400">{activeStrategy}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-8">
           <button 
             onClick={() => setAutoPilot(!autoPilot)}
             className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all border ${autoPilot ? 'bg-blue-600 border-blue-400 text-white' : 'bg-white/5 border-white/10 text-slate-500'}`}
           >
             Auto-Pilot: {autoPilot ? 'ON' : 'OFF'}
