            {isTyping && <div className="text-blue-500 animate-pulse text-[10px] font-black uppercase tracking-widest text-right">Autonomous Thinking...</div>}
          </div>

          <div className="p-10 bg-black/80 border-t border-white/5 backdrop-blur-3xl">
