const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear, scamLibrary = [] }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const recognitionRef = useRef<any>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    // Initialize Speech Recognition
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = 'en-IN';

      recognitionRef.current.onresult = (event: any) => {
        let interimTranscript = '';
        let finalTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }

        if (finalTranscript) {
          setInput(prev => prev + (prev ? ' ' : '') + finalTranscript);
        }
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current.onerror = (event: any) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);
      };
    }

    // Close suggestions when clicking outside
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleInputChange = (val: string) => {
    setInput(val);
    if (val.length > 1) {
      const filtered = COMMON_SCAM_PHRASES.filter(phrase => 
        phrase.toLowerCase().includes(val.toLowerCase())
      );
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
      setFocusedIndex(-1);
    } else {
      setShowSuggestions(false);
    }
  };

  const selectSuggestion = (suggestion: string) => {
    setInput(suggestion);
    setShowSuggestions(false);
    if (inputRef.current) inputRef.current.focus();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!showSuggestions) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedIndex(prev => (prev > 0 ? prev - 1 : prev));
    } else if (e.key === 'Enter' && focusedIndex >= 0) {
      e.preventDefault();
      selectSuggestion(suggestions[focusedIndex]);
    } else if (e.key === 'Escape') {
      setShowSuggestions(false);
    }
  };

  const toggleListening = () => {
    if (!recognitionRef.current) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      recognitionRef.current.start();
      setIsListening(true);
    }
  };

  const handleAnalyze = async () => {
    if (!input.trim()) return;
    if (isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    }

    setLoading(true);
    onAnalysisStart();
    setShowSuggestions(false);
    try {
      const result = await analyzeMessage(input, scamLibrary);
      onAnalysisComplete(input, result);
      // Auto-scroll to results
      setTimeout(() => {
        document.getElementById('results-anchor')?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-left-4 duration-1000" ref={containerRef}>
      <div className="bg-[#0f172a]/40 rounded-[3rem] border border-blue-500/20 overflow-hidden relative shadow-2xl backdrop-blur-sm group p-1 ring-1 ring-blue-500/10">
        <div className="bg-black/80 rounded-[2.8rem] p-10 space-y-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
             <div className="space-y-1">
                <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">Input Terminal</h3>
                <p className="text-lg font-bold text-white tracking-tight uppercase">Buffered Interception Intake</p>
             </div>
             <div className="flex items-center space-x-4">
                <button 
                  onClick={() => {
                    setSuggestions(COMMON_SCAM_PHRASES);
                    setShowSuggestions(!showSuggestions);
                  }}
                  className="px-4 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl text-[9px] font-black text-blue-500 uppercase tracking-widest hover:bg-blue-500/20 transition-all"
                >
                  {showSuggestions ? 'Hide Library' : 'Browse Library'}
                </button>
                {isListening && (
                  <div className="flex items-center space-x-2 bg-red-500/10 border border-red-500/20 px-3 py-1 rounded-full animate-pulse">
                    <div className="w-1.5 h-1.5 bg-red-500 rounded-full" />
                    <span className="text-[8px] font-black text-red-500 uppercase tracking-widest">Acoustic_Stream_Active</span>
                  </div>
                )}
             </div>
          </div>

          <div className="relative">
             <div className="absolute -inset-1 bg-gradient-to-r from-blue-600/20 to-cyan-400/20 rounded-[2.5rem] blur opacity-25 group-focus-within:opacity-100 transition duration-1000" />
             <textarea
               ref={inputRef}
               className="relative w-full h-64 p-8 bg-black/60 border border-white/5 rounded-[2.5rem] text-white focus:ring-1 focus:ring-blue-500/50 outline-none transition-all resize-none text-xl font-medium placeholder:text-slate-800 leading-relaxed font-mono"
               placeholder=">>> PASTE MESSAGE OR USE MIC TO DICTATE..."
               value={input}
               onChange={(e) => handleInputChange(e.target.value)}
               onKeyDown={handleKeyDown}
               onFocus={() => input.length > 1 && suggestions.length > 0 && setShowSuggestions(true)}
             />

             {/* Autocomplete Suggestions */}
             {showSuggestions && (
               <div className="absolute left-0 right-0 top-full mt-2 bg-[#0a0f1d] border border-blue-500/30 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.9)] z-50 overflow-hidden backdrop-blur-3xl animate-in fade-in slide-in-from-top-2 border-t-blue-500/50">
                 <div className="px-6 py-4 border-b border-white/5 bg-black/40 flex justify-between items-center">
                    <span className="text-[8px] font-black text-blue-500 uppercase tracking-[0.4em]">Matching Fraud Patterns_Detected</span>
                    <span className="text-[8px] font-mono text-slate-500 uppercase">Use ↑↓ Keys</span>
                 </div>
                 <div className="max-h-72 overflow-y-auto no-scrollbar py-2">
                   {suggestions.map((phrase, idx) => (
                     <button
                       key={idx}
                       onMouseEnter={() => setFocusedIndex(idx)}
                       onClick={() => selectSuggestion(phrase)}
                       className={`w-full text-left px-8 py-4 text-xs transition-all border-b border-white/5 last:border-0 font-medium flex items-start space-x-4 ${
                         focusedIndex === idx 
                         ? 'bg-blue-600/20 text-white' 
                         : 'text-slate-400 hover:text-slate-200'
                       }`}
                     >
                       <span className={`mt-1 text-[8px] font-mono transition-opacity ${focusedIndex === idx ? 'text-blue-400 opacity-100' : 'text-slate-700 opacity-50'}`}>
                         [{String(idx + 1).padStart(2, '0')}]
                       </span>
                       <span className="flex-1">{phrase}</span>
                       {focusedIndex === idx && (
                         <span className="text-[10px] text-blue-500 animate-pulse">↲</span>
                       )}
                     </button>
                   ))}
                 </div>
               </div>
             )}

             {/* Microphone Button */}
             <button
               onClick={toggleListening}
               className={`absolute bottom-8 right-8 w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 z-10 border ${
                 isListening 
                 ? 'bg-red-600 border-red-400 text-white shadow-[0_0_20px_rgba(220,38,38,0.5)] scale-110' 
                 : 'bg-blue-600/10 border-blue-500/30 text-blue-500 hover:bg-blue-600 hover:text-white'
               }`}
               title={isListening ? "Stop Listening" : "Start Voice Input"}
             >
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
               </svg>
               {isListening && <div className="absolute -inset-2 border-2 border-red-500 rounded-[1.5rem] animate-ping opacity-30 pointer-events-none" />}
             </button>
          </div>

          <div className="flex flex-col sm:flex-row gap-4">
            <button
              onClick={handleAnalyze}
              disabled={loading || input.length < 5}
              className={`flex-1 py-6 rounded-[2rem] font-black text-lg tracking-[0.2em] shadow-2xl transition-all flex items-center justify-center space-x-4 relative overflow-hidden active:scale-95 ${loading ? 'bg-slate-800 text-slate-500' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
            >
              {loading ? (
                <div className="flex items-center space-x-4">
                   <div className="w-5 h-5 border-3 border-slate-700 border-t-blue-500 rounded-full animate-spin"></div>
                   <span className="uppercase tracking-[0.3em] text-sm">Analyzing Pattern...</span>
                </div>
              ) : (
                <>
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                  <span className="uppercase tracking-[0.4em] text-sm">Engage Defense Protocol</span>
                </>
              )}
            </button>
            <button
               onClick={() => {setInput(''); onClear(); setShowSuggestions(false);}}
               className="px-10 py-6 bg-white/5 border border-white/10 rounded-[2rem] text-slate-500 hover:text-white hover:bg-white/10 transition-all font-black uppercase text-xs tracking-widest"
            >
              Clear
            </button>
          </div>
        </div>
      </div>

      {/* Quick Injection Presets */}
      <div className="flex flex-wrap gap-3">
        <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest flex items-center mr-2">Quick Test Scripts:</span>
        {SCAM_SCENARIOS.map((s, idx) => (
          <button 
            key={idx}
            onClick={() => setInput(s.msg)}
            className="px-4 py-2 bg-white/5 hover:bg-blue-600/20 border border-white/5 rounded-xl text-[9px] font-black text-slate-500 hover:text-blue-400 uppercase tracking-widest transition-all"
          >
            {s.label}
          </button>
        ))}
      </div>
    </div>
  );
};

