import ForensicLab from './components/ForensicLab';
import WarRoom from './components/WarRoom';
import OnboardingTour from './components/OnboardingTour';
import { ScamAnalysis, IntelligenceLog, ForensicDossier, ScamSignature } from './types';
import { generateSimulatedCase } from './utils/scamGenerator';
import { analyzeMessage } from './services/geminiService';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'intelligence' | 'warroom' | 'history' | 'multimedia'>('analyzer');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simProgress, setSimProgress] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);
  const [isTrialRunning, setIsTrialRunning] = useState(false);
  const [diagnosticLog, setDiagnosticLog] = useState<string[]>([]);

  const scamLibrary = useMemo((): ScamSignature[] => {
    return logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
          ...l.extractedInfo.upiIds.map(u => u.value),
          ...l.extractedInfo.phoneNumbers.map(p => p.value),
          ...l.extractedInfo.links.map(link => link.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 50 ? l.originalMessage.substring(0, 50) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Generic",
          method: l.channel.toUpperCase(),
          link: l.extractedInfo.links[0]?.value || "N/A"
        }
      }));
  }, [logs]);

  const currentSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const has = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      }
    };
    checkKey();

    const hasVisited = localStorage.getItem('rakshak_visited');
    if (!hasVisited) {
      setShowTutorial(true);
      localStorage.setItem('rakshak_visited', 'true');
    }
  }, []);

  const handleKeySelect = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const runSimulation = (count: number = 500) => {
    setIsSimulating(true);
    setSimProgress(0);
    setView('intelligence');
    let currentCount = 0;
    const batchSize = 25;
    const interval = setInterval(() => {
      const nextBatch = [];
      for(let i = 0; i < batchSize && currentCount < count; i++) {
        const id = `SIM-${Date.now()}-${currentCount}`;
        const simulated = generateSimulatedCase(id);
        nextBatch.push(simulated);
        currentCount++;
      }
      setLogs(prev => [...nextBatch, ...prev]);
      setSimProgress(Math.round((currentCount / count) * 100));
      if (currentCount >= count) {
        clearInterval(interval);
        setIsSimulating(false);
      }
    }, 150);
  };

  const handleManualAnalyze = async (message: string) => {
    const analysisResult = await analyzeMessage(message, scamLibrary);
    handleAnalysisComplete(message, analysisResult, true);
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedCases = logs.filter(prevLog => {
      if (prevLog.id === sessionId) return false;
      const upiMatch = analysis.extractedInfo.upiIds.some(u => 
        prevLog.extractedInfo.upiIds.some(pu => pu.value.toLowerCase() === u.value.toLowerCase())
      );
      const linkMatch = analysis.extractedInfo.links.some(l => 
        prevLog.extractedInfo.links.some(pl => pl.value === l.value)
      );
      return upiMatch || linkMatch;
    }).map(l => l.id);

    const existingLog = logs.find(l => l.id === sessionId);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: linkedCases,
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: 'Active Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? (existingLog ? existingLog.messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
    };

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical' || linkedCases.length > 0 || analysis.patternMatch?.isSimilar) {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.patternMatch?.isSimilar ? "HISTORICAL PATTERN DETECTED" : analysis.safetyAlert,
        details: analysis.patternMatch?.correlationLogic || "Deploying Sovereign Agent for extraction.",
        isEngaging: true
      });
    }
  };

  const initiateSystemTrial = async () => {
    setIsTrialRunning(true);
    setView('analyzer');
    setDiagnosticLog(["INITIALIZING_SYSTEM_TRIAL", "SUBSYSTEM_CHECK: NEURAL_ENGINE... OK", "SUBSYSTEM_CHECK: WEB_GROUNDING... OK"]);

    const trialMessage = "This is Officer Vikram from Mumbai Cyber Crime Branch. We have found 5kg of illegal narcotics in a FedEx parcel linked to your Aadhaar. You must join a Skype video call immediately for a 'Digital Arrest' statement or face a 10-year prison sentence. Join: cbi-official-arrest-node-5.paytm";

    setTimeout(() => setDiagnosticLog(prev => ["INJECTING_FORENSIC_PAYLOAD", ...prev]), 1000);

    try {
      const result = await analyzeMessage(trialMessage, scamLibrary);
      handleAnalysisComplete(trialMessage, result, true);
      setDiagnosticLog(prev => ["ANALYSIS_COMPLETE", "SCAM_CONFIRMED: HIGH_CONFIDENCE", "NAVIGATING_TO_FORENSIC_HUD", ...prev]);

      setTimeout(() => {
        document.getElementById('results-anchor')?.scrollIntoView({ behavior: 'smooth' });
        setIsTrialRunning(false);
      }, 2000);
    } catch (e) {
      setDiagnosticLog(prev => ["TRIAL_ERROR: " + e, ...prev]);
      setIsTrialRunning(false);
    }
  };

  const handleForensicFinalized = (dossier: ForensicDossier) => {
    if (!currentSessionIdRef.current) return;
    const sessionId = currentSessionIdRef.current;
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, forensicReport: dossier } : l));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {isTrialRunning && (
        <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl flex items-center justify-center p-6">
           <div className="max-w-xl w-full space-y-8 animate-in zoom-in-95 duration-500">
              <div className="flex flex-col items-center space-y-6 text-center">
                 <div className="w-20 h-20 border-4 border-blue-500 border-t-transparent rounded-full animate-spin shadow-[0_0_30px_blue]"></div>
                 <div className="space-y-2">
                    <h2 className="text-3xl font-black text-white uppercase tracking-tighter">System Diagnostic Trial</h2>
                    <p className="text-blue-500 font-mono text-xs uppercase tracking-[0.3em]">Executing End-to-End Forensic Protocol</p>
                 </div>
              </div>
              <div className="bg-slate-900/50 border border-white/5 p-8 rounded-3xl h-64 overflow-y-auto no-scrollbar font-mono text-[10px] text-blue-400/80 space-y-2">
                 {diagnosticLog.map((log, i) => (
                    <div key={i} className="flex items-center space-x-3 animate-in slide-in-from-left-2">
                       <span className="text-slate-700">[{new Date().toLocaleTimeString()}]</span>
                       <span>>> {log}</span>
                    </div>
                 ))}
              </div>
           </div>
