    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical' || linkedCases.length > 0 || analysis.patternMatch?.isSimilar) {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.patternMatch?.isSimilar ? "HISTORICAL PATTERN DETECTED" : analysis.safetyAlert,
        details: analysis.patternMatch?.correlationLogic || "Deploying Sovereign Agent for extraction.",
        isEngaging: true
      });
    }
  };

  const initiateSystemTrial = async () => {
    setIsTrialRunning(true);
    setView('analyzer');
    setDiagnosticLog(["INITIALIZING_SYSTEM_TRIAL", "SUBSYSTEM_CHECK: NEURAL_ENGINE... OK", "SUBSYSTEM_CHECK: WEB_GROUNDING... OK"]);

    const trialMessage = "This is Officer Vikram from Mumbai Cyber Crime Branch. We have found 5kg of illegal narcotics in a FedEx parcel linked to your Aadhaar. You must join a Skype video call immediately for a 'Digital Arrest' statement or face a 10-year prison sentence. Join: cbi-official-arrest-node-5.paytm";

    setTimeout(() => setDiagnosticLog(prev => ["INJECTING_FORENSIC_PAYLOAD", "RUNNING_HEURISTIC_ANALYSIS", ...prev]), 1000);

    try {
      const result = await analyzeMessage(trialMessage, scamLibrary);
      handleAnalysisComplete(trialMessage, result, true);
      setDiagnosticLog(prev => ["SCAM_CONFIRMED", "NAVIGATING_TO_EVIDENCE_MAP", ...prev]);

      setTimeout(() => {
        setIsTrialRunning(false);
        setTimeout(() => {
          const anchor = document.getElementById('results-anchor');
          if (anchor) anchor.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }, 1500);
    } catch (e) {
      setDiagnosticLog(prev => ["SYSTEM_TIMEOUT: Retrying with alternate node...", ...prev]);
      setIsTrialRunning(false);
    }
  };

  const handleForensicFinalized = (dossier: ForensicDossier) => {
    if (!currentSessionIdRef.current) return;
    const sessionId = currentSessionIdRef.current;
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, forensicReport: dossier } : l));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {isTrialRunning && (
        <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-6">
           <div className="max-w-xl w-full space-y-8 animate-in zoom-in-95 duration-500">
              <div className="flex flex-col items-center space-y-6 text-center">
                 <div className="w-20 h-20 border-4 border-blue-600 border-t-transparent rounded-full animate-spin shadow-[0_0_40px_rgba(37,99,235,0.4)]"></div>
                 <div className="space-y-2">
                    <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Diagnostic Trial Active</h2>
                    <p className="text-blue-500 font-mono text-[10px] uppercase tracking-[0.3em]">Executing End-to-End Forensic Protocol</p>
                 </div>
              </div>
              <div className="bg-slate-900/50 border border-white/5 p-8 rounded-3xl h-64 overflow-y-auto no-scrollbar font-mono text-[10px] text-blue-400/80 space-y-2 shadow-inner">
                 {diagnosticLog.map((log, i) => (
                    <div key={i} className="flex items-center space-x-3 animate-in slide-in-from-left-2">
                       <span className="text-slate-700">[{new Date().toLocaleTimeString()}]</span>
                       <span className={log.includes('CONFIRMED') ? 'text-green-500' : ''}>>> {log}</span>
                    </div>
                 ))}
              </div>
              <div className="flex justify-center">
                 <button 
                   onClick={() => setIsTrialRunning(false)}
                   className="text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest transition-colors py-2 px-4 border border-white/5 rounded-xl"
                 >
                   Force Exit Diagnostic
                 </button>
              </div>
           </div>
        </div>
      )}

      {showTutorial && (
        <OnboardingTour 
          activeView={view} 
          onViewChange={(v) => setView(v)} 
          onComplete={() => setShowTutorial(false)} 
        />
      )}

      <header className="glass-panel px-4 lg:px-10 py-4 lg:py-6 flex flex-wrap items-center justify-between sticky top-0 z-[60] border-b border-white/10 gap-4">
        <div className="flex items-center space-x-3 lg:space-x-6">
          <div className="bg-blue-600 p-2 lg:p-3 rounded-xl lg:rounded-2xl shadow-[0_0_25px_rgba(37,99,235,0.4)] glow-cobalt shrink-0">
            <svg className="w-5 h-5 lg:w-6 lg:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('analyzer'); setLatestAnalysis(null);}} className="text-left group">
            <h1 className="text-lg lg:text-2xl font-black tracking-tighter text-white uppercase group-hover:text-blue-400 transition-colors">BHARAT CYBER <span className="text-blue-500">RAKSHAK</span></h1>
            <p className="text-[7px] lg:text-[9px] text-slate-500 font-black uppercase tracking-[0.5em] font-mono">SOVEREIGN_AGENT_GRID_v2.5</p>
          </button>
        </div>

        <nav className="hidden xl:flex items-center space-x-2 bg-white/5 p-1.5 rounded-2xl border border-white/10">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Containment" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Map" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia Intel" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="Sovereign War Room" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Dossiers" />
        </nav>

        <div className="flex items-center space-x-3 lg:space-x-8">
           <button 
             onClick={initiateSystemTrial}
             className="flex items-center space-x-2 lg:space-x-3 bg-blue-600 hover:bg-blue-500 px-4 lg:px-6 py-2 lg:py-2.5 rounded-lg lg:rounded-xl shadow-[0_0_20px_rgba(37,99,235,0.4)] transition-all group relative overflow-visible"
           >
              <div className="absolute -top-2 -right-2 bg-red-500 text-white text-[7px] font-black px-1.5 py-0.5 rounded-full animate-bounce shadow-lg">TEST_MODE</div>
              <svg className="w-3.5 h-3.5 lg:w-4 lg:h-4 text-white group-hover:animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              <span className="text-[8px] lg:text-[10px] font-black text-white uppercase tracking-widest">Diagnostic Trial</span>
           </button>
           <button 
             onClick={() => setShowTutorial(true)}
             className="flex items-center space-x-2 bg-white/5 hover:bg-white/10 px-3 lg:px-4 py-2 rounded-lg lg:rounded-xl border border-white/10 transition-all group"
           >
              <svg className="w-3.5 h-3.5 lg:w-4 lg:h-4 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              <span className="text-[8px] lg:text-[10px] font-black text-slate-300 uppercase tracking-widest">Tutorial</span>
           </button>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'warroom' ? (
          <WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} onOpenKey={handleKeySelect} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : view === 'multimedia' ? (
          <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <VoiceSynthesisLab />
                <VideoScanner />
             </div>
          </div>
        ) : (
          <div className="space-y-16">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start pt-8">
              <div className="lg:col-span-7 space-y-10">
                <h2 className="text-4xl lg:text-6xl font-black text-white tracking-tighter uppercase leading-none">
                  ADAPTIVE <span className="text-blue-500">DEFENSE</span> INTERFACE
                </h2>
                <ScamAnalyzer 
                   onAnalysisComplete={(msg) => handleManualAnalyze(msg)} 
                   onAnalysisStart={() => {}} 
                   onClear={() => setLatestAnalysis(null)} 
                   scamLibrary={scamLibrary}
                   onRunTrial={initiateSystemTrial}
                />
              </div>
              <div className="lg:col-span-5 space-y-6">
                <div className="bg-white/5 border border-white/10 rounded-[3rem] p-10 space-y-8">
                  <h3 className="text-sm font-black text-blue-500 uppercase tracking-[0.4em]">Adaptive Learning Stats</h3>
                  <div className="grid grid-cols-2 gap-4">
                     <MemoryStat label="Archived Patterns" value={scamLibrary.length} />
                     <MemoryStat label="Trapped Identifiers" value={scamLibrary.reduce((acc, s) => acc + s.extractedIndicators.length, 0)} />
                  </div>
                  <div className="pt-6 border-t border-white/10">
                    <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic">
                        "System maintains an internal 'scam_memory.json' context for high-fidelity pattern matching."
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {latestAnalysis && (
              <div id="results-anchor" className="space-y-24 animate-in slide-in-from-bottom-20 duration-1000 pt-16 border-t border-white/5">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[900px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                      onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                      onForensicFinalized={handleForensicFinalized}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${active ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
    {label}
  </button>
);

const MemoryStat = ({ label, value }: any) => (
  <div className="bg-black/40 p-6 rounded-2xl border border-white/5">
     <div className="text-[9px] font-black text-slate-500 uppercase mb-2">{label}</div>
     <div className="text-2xl font-black text-white">{value}</div>
  </div>
);

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { IntelligenceLog, AnalyticsSummary, ThreatPosture, ScamSignature } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'library' | 'adaptive'>('overview');
  const [globalStream, setGlobalStream] = useState<any[]>([]);

  useEffect(() => {
    const events = [
      "Agent 'Kore' intercepted UPI handle in Jamtara cluster.",
      "Autonomous bypass of remote-access request detected.",
      "New Phishing pattern identified in urban Delhi-NCR zone.",
      "Scammer psychological suspicion increased to 45% (Mumbai).",
      "Synthetic Identity 'Officer Sharma' successfully deployed.",
      "Institutional block request sent to SBI for account: 9182***"
    ];
    const interval = setInterval(() => {
      setGlobalStream(prev => [events[Math.floor(Math.random() * events.length)], ...prev].slice(0, 5));
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);

    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000);
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 20) threatPosture = 'Red';
    else if (recentLogs.length > 10) threatPosture = 'Yellow';

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...(log.extractedInfo?.upiIds || []).map(i => ({ v: i.value, t: 'UPI' })),
        ...(log.extractedInfo?.phoneNumbers || []).map(i => ({ v: i.value, t: 'TEL' })),
        ...(log.extractedInfo?.links || []).map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const library: ScamSignature[] = logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
            ...(l.extractedInfo?.upiIds || []).map(u => u.value),
            ...(l.extractedInfo?.phoneNumbers || []).map(p => p.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 60 ? l.originalMessage.substring(0, 60) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Multiple",
          method: l.channel.toUpperCase(),
          link: (l.extractedInfo?.links && l.extractedInfo.links[0]?.value) || "N/A"
        }
      }));

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: totalPrevention * 1.5,
      threatPosture,
      topIdentifiers,
      scamLibrary: library,
      honeypotSuccessRate: logs.filter(l => l.messages.length > 2).length ? (logs.filter(l => (l.extractedInfo?.upiIds || []).length > 0).length / logs.filter(l => l.messages.length > 2).length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: 98,
        complianceRate: 100
      }
    };
  }, [logs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50 border-green-100',
    'Yellow': 'text-amber-600 bg-amber-50 border-amber-100',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
  }[analytics.threatPosture];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-8 rounded-[2rem] border shadow-2xl flex flex-col justify-center transition-all ${postureColor}`}>
           <div className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-60">Sovereign Defense Nodes</div>
           <div className="text-4xl font-black tracking-tighter uppercase">{analytics.threatPosture} ALERT</div>
           <div className="mt-2 text-[9px] font-bold text-slate-500 uppercase tracking-widest font-mono">Shielding: National Grid</div>
        </div>
        <KPIBox title="Shielded Assets" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Interception Value" color="text-blue-600" />
        <KPIBox title="Memory Store" value={analytics.scamLibrary.length} sub="Unique Scam Patterns" color="text-indigo-600" />
        <KPIBox title="Extraction Quality" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Data Siphoning Rate" color="text-emerald-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Tactical Grid" />
        <TabNav active={activeTab === 'library'} onClick={() => setActiveTab('library')} label="Memory Store (JSON)" />
        <TabNav active={activeTab === 'adaptive'} onClick={() => setActiveTab('adaptive')} label="Pattern Trends" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-8 space-y-8">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl space-y-10">
                 <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
                    <div className="w-2.5 h-2.5 bg-blue-600 rounded-full mr-3 animate-pulse" />
                    Global Threat Hotspots
                 </h3>
                 <div className="aspect-video bg-slate-50 rounded-3xl border border-slate-100 relative overflow-hidden group">
                    <div className="absolute inset-0 opacity-5 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#1e293b 0.5px, transparent 0.5px)', backgroundSize: '24px 24px' }} />
                    {logs.filter(l => l.sourceIntelligence?.coordinates).slice(0, 50).map((log) => (
                       <div 
                         key={log.id} 
                         className="absolute group/blip cursor-pointer" 
                         style={{ 
                           top: `${15 + (log.sourceIntelligence?.coordinates?.lat || 0) % 70}%`, 
                           left: `${15 + (log.sourceIntelligence?.coordinates?.lng || 0) % 70}%` 
                         }}
                       >
                         <div className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-xl ${log.threatLevel === 'Critical' ? 'bg-red-500' : 'bg-blue-600'}`} />
                       </div>
                    ))}
                 </div>
              </div>

              {/* Global Engagement Stream */}
              <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl space-y-6 text-white overflow-hidden relative">
                  <div className="absolute top-0 right-0 p-10 opacity-5">
                    <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-13h2v6h-2zm0 8h2v2h-2z" /></svg>
                  </div>
                  <h3 className="text-sm font-black text-blue-400 uppercase tracking-widest flex items-center">
                    <div className="w-2 h-2 bg-blue-500 rounded-full mr-3 animate-ping" />
                    Autonomous Engagement Feed (Global)
                  </h3>
                  <div className="space-y-3 font-mono text-[11px] leading-relaxed">
                    {globalStream.map((event, i) => (
                      <div key={i} className="flex space-x-4 animate-in slide-in-from-left-4 duration-500">
                        <span className="text-slate-500">[{new Date().toLocaleTimeString()}]</span>
                        <span className="text-blue-300">>> {event}</span>
                      </div>
                    ))}
                    {globalStream.length === 0 && <span className="text-slate-700 italic">Initializing sovereign stream...</span>}
                  </div>
              </div>
           </div>

           <div className="lg:col-span-4 bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center mb-8">
                 <div className="w-2 h-2 bg-indigo-600 rounded-full mr-3" />
                 Indicator Persistence
              </h3>
              <div className="space-y-3">
                 {analytics.topIdentifiers.slice(0, 6).map((id, i) => (
                   <div key={i} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                      <div className="flex flex-col">
                         <span className="text-[8px] font-black text-indigo-600 uppercase mb-1 tracking-widest">{id.type}</span>
                         <span className="text-[11px] font-mono font-bold text-slate-800 truncate max-w-[120px]">{id.value}</span>
                      </div>
                      <div className="text-[10px] font-black text-slate-900">{id.count} Hits</div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'library' && (
        <div className="space-y-8 bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
            <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <div>
                    <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Pattern Memory Store</h2>
                    <p className="text-sm text-slate-500 font-medium mt-1">Structured repository of verified fraud signatures used for autonomous similarity detection.</p>
                </div>
                <div className="flex space-x-2">
                    <button className="px-6 py-3 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-500 transition-all shadow-lg">Download Memory (JSON)</button>
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-900 text-white">
                            <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Pattern Message</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Bank</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Method</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Malicious Link</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Extracted</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {analytics.scamLibrary.map((s, i) => (
                            <tr key={i} className="hover:bg-blue-50 transition-colors group">
                                <td className="px-8 py-6 text-[12px] font-medium text-slate-700 italic max-w-[300px] truncate leading-relaxed">
                                    "{s.patternMeta.pattern}"
                                </td>
                                <td className="px-8 py-6">
                                    <span className="text-[10px] font-black text-slate-900 uppercase bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                                        {s.patternMeta.bank}
                                    </span>
                                </td>
                                <td className="px-8 py-6">
                                    <span className="text-[10px] font-black text-blue-600 uppercase">
                                        {s.patternMeta.method}
                                    </span>
                                </td>
                                <td className="px-8 py-6 max-w-[200px] overflow-hidden">
                                    <div className="text-[11px] font-mono text-slate-400 truncate bg-slate-50 p-2 rounded-lg border border-slate-100 group-hover:bg-white transition-colors">
                                        {s.patternMeta.link}
                                    </div>
                                </td>
                                <td className="px-8 py-6 text-right">
                                    <div className="text-[10px] font-mono text-slate-400">
                                        {new Date(s.timestamp).toLocaleDateString()}
                                    </div>
                                    <div className="text-[10px] font-mono text-slate-400">
                                        {new Date(s.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {analytics.scamLibrary.length === 0 && (
                    <div className="py-32 text-center">
                        <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6 border border-slate-100">
