                        </div>
                        <p className="text-sm font-black uppercase text-slate-300 tracking-[0.4em]">Memory Store Initializing...</p>
                    </div>
                )}
            </div>
        </div>
      )}

      {activeTab === 'adaptive' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           <PatternCard title="Digital Arrest Loop" level="Critical" desc="Scammers use Mumbai Police video-call bait to extort professional data." count={logs.filter(l => l.scamType.includes('Police')).length} />
           <PatternCard title="Part-time Job Trap" level="High" desc="Luring fresh graduates with daily payout tasks before exit-scamming higher deposits." count={logs.filter(l => l.scamType.includes('Job')).length} />
