import React, { useState } from 'react';
import { KillChainStage, ScamAnalysis } from '../types';
import { maskValue } from '../utils/masking';

interface Props {
  analysis: ScamAnalysis;
}

const stages: KillChainStage[] = ['Reconnaissance', 'Delivery', 'Exploitation', 'Actions on Objective'];

const KillChainVisualizer: React.FC<Props> = ({ analysis }) => {
  const [selectedStage, setSelectedStage] = useState<KillChainStage>(analysis.killChainStage);
  const currentIndex = stages.indexOf(analysis.killChainStage);
  const selectedIndex = stages.indexOf(selectedStage);

  const getStageContent = (stage: KillChainStage) => {
    switch (stage) {
      case 'Reconnaissance':
        return (
          <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Inferred Origin</span>
              <span className="text-[10px] font-bold text-white uppercase">{analysis.sourceIntelligence?.likelyOrigin || 'Unknown'}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Cluster Map</span>
              <span className="text-[10px] font-bold text-blue-400 font-mono">ID: {analysis.sourceIntelligence?.clusterId || 'PENDING'}</span>
            </div>
            <p className="text-[10px] text-slate-400 italic leading-relaxed pt-1">
              Threat infrastructure reconnaissance detected. Cluster intelligence suggests targeting of {analysis.sourceIntelligence?.institutionInference || 'financial users'}.
            </p>
          </div>
        );
      case 'Delivery':
        return (
          <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Medium</span>
              <span className="text-[10px] font-bold text-white uppercase">{analysis.channel}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Category</span>
              <span className="text-[10px] font-bold text-white uppercase">{analysis.fingerprint.category}</span>
            </div>
            <p className="text-[10px] text-slate-400 italic leading-relaxed pt-1">
              The malicious payload reached the target device. Behavioral markers indicate high-urgency social engineering.
            </p>
          </div>
        );
      case 'Exploitation':
        return (
          <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
            <div className="flex items-center justify-between">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Indicators Found</span>
              <span className="text-[9px] font-black text-red-500 bg-red-500/10 px-2 py-0.5 rounded border border-red-500/20">MALICIOUS</span>
            </div>
            <div className="flex flex-wrap gap-1.5 max-h-16 overflow-y-auto no-scrollbar">
              {(analysis.extractedInfo?.upiIds || []).map((u, i) => (
                <span key={i} className="text-[8px] font-mono text-slate-300 bg-white/5 px-1.5 py-0.5 rounded border border-white/5">{maskValue(u.value, 'UPI')}</span>
              ))}
              {(analysis.extractedInfo?.links || []).map((l, i) => (
                <span key={i} className="text-[8px] font-mono text-slate-300 bg-white/5 px-1.5 py-0.5 rounded border border-white/5">{maskValue(l.value, 'URL')}</span>
              ))}
              {(analysis.extractedInfo?.phoneNumbers || []).map((p, i) => (
                <span key={i} className="text-[8px] font-mono text-slate-300 bg-white/5 px-1.5 py-0.5 rounded border border-white/5">{maskValue(p.value, 'PHONE')}</span>
              ))}
            </div>
            <p className="text-[10px] text-slate-400 italic leading-relaxed pt-1">
              Attacker attempted to gain credentials or financial access via provided links/UPI handles.
            </p>
          </div>
        );
      case 'Actions on Objective':
        return (
          <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Impact Potential</span>
              <span className="text-[10px] font-bold text-red-500 font-mono">₹{analysis.potentialImpact?.toLocaleString() || 'High'}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Shield Status</span>
              <span className="text-[10px] font-bold text-green-500 uppercase">Containment Queued</span>
            </div>
            <p className="text-[10px] text-slate-400 italic leading-relaxed pt-1">
              Final stage reached. Scammer is attempting financial extraction. Rakshak AI is actively siphoning counter-intel.
            </p>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="bg-slate-950/50 rounded-2xl border border-white/10 p-6 space-y-6">
