        <div 
          className="absolute top-1/2 left-0 h-0.5 bg-blue-500 -translate-y-1/2 z-0 transition-all duration-1000" 
          style={{ width: `${(currentIndex / (stages.length - 1)) * 100}%` }} 
        />

        {stages.map((stage, idx) => {
          const isPast = idx < currentIndex;
          const isCurrent = idx === currentIndex;
          const isFuture = idx > currentIndex;
          const isSelected = stage === selectedStage;

          return (
            <button 
              key={stage} 
              onClick={() => setSelectedStage(stage)}
              className="relative z-10 flex flex-col items-center group transition-all"
            >
              <div className={`w-6 h-6 rounded-full border-2 transition-all duration-500 flex items-center justify-center ${
                isSelected ? 'bg-blue-600 border-white shadow-[0_0_20px_#3b82f6]' : 
                (isPast || isCurrent) ? 'bg-blue-600 border-blue-400' : 'bg-slate-800 border-slate-700'
              } ${isCurrent ? 'animate-pulse' : ''} group-hover:scale-110`}>
                {isPast && (
                  <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                )}
                {isCurrent && <div className="w-1.5 h-1.5 bg-white rounded-full" />}
              </div>
              <span className={`mt-3 text-[8px] font-black uppercase tracking-tighter text-center max-w-[50px] transition-colors ${
                isSelected ? 'text-white' : (isPast || isCurrent) ? 'text-blue-400' : 'text-slate-600'
              }`}>
                {stage.split(' ').length > 1 ? stage.split(' ')[0] : stage}
              </span>
            </button>
          );
        })}
      </div>

      <div className="bg-black/40 rounded-xl border border-white/5 p-4 min-h-[110px] flex flex-col justify-center">
        <div className="flex items-center space-x-2 mb-3">
          <span className="text-[9px] font-black text-blue-500 uppercase tracking-widest">{selectedStage} Details</span>
          <div className="h-px flex-1 bg-white/5" />
        </div>
        {getStageContent(selectedStage)}
      </div>

      <div className="text-[8px] font-bold text-slate-600 text-center uppercase tracking-widest">
        Click a stage node for tactical forensic summary
      </div>
    </div>
  );
};

