              className={`flex-1 py-4 lg:py-6 rounded-[1.5rem] lg:rounded-[2rem] font-black text-sm lg:text-lg tracking-[0.2em] shadow-2xl transition-all flex items-center justify-center space-x-4 relative overflow-hidden active:scale-95 ${loading ? 'bg-slate-800 text-slate-500' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
            >
