            </button>
            <button
               onClick={() => {setInput(''); onClear(); setIsLibraryForcedOpen(false);}}
               className="px-6 lg:px-10 py-4 lg:py-6 bg-white/5 border border-white/10 rounded-[1.5rem] lg:rounded-[2rem] text-slate-500 hover:text-white hover:bg-white/10 transition-all font-black uppercase text-[10px] lg:text-xs tracking-widest"
            >
