import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage } from '../services/geminiService';
import { ScamAnalysis, ScamSignature } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
  onAnalysisStart: () => void;
  onClear: () => void;
  scamLibrary?: ScamSignature[];
  onRunTrial?: () => void;
}

const SCAM_SCENARIOS = [
  { label: "Police Impersonation", msg: "This is CBI Officer Sharma. Your Aadhaar is linked to a money laundering case. Join Skype: cbi-official-verify-99. Failure will result in immediate arrest." },
  { label: "KYC Phishing", msg: "HDFC Alert: Your NetBanking is suspended due to missing KYC. Verify at https://hdfc-kyc-verify.in/auth or your account will be frozen permanently." },
  { label: "Part-time Job", msg: "Earn 5000-8000 daily working from home! Just follow our Telegram channel for tasks: t.me/profit_tasks_india. No experience needed." },
  { label: "Power Cut-off", msg: "MSEDCL Update: Your power will be disconnected at 9PM today due to pending dues. Call 700-123-4455 to clear balance immediately." }
];

const COMMON_SCAM_PHRASES = [
  "Your Aadhaar is linked to a money laundering case. Transfer funds for verification.",
  "Your electricity bill is pending, power will be disconnected at 9PM today.",
  "Congratulations! You have won a lottery of 25 lakhs in KBC. Call now.",
  "I am calling from Mumbai Police regarding your illegal parcel found in Customs.",
  "Your bank account has been suspended due to missing KYC. Click to verify.",
  "Immediate payment of fine required to avoid judicial arrest and jail.",
  "Dear Customer, your SBI YONO account will be blocked today due to security reasons.",
  "Your FedEx parcel contains illegal substances and drugs. Contact narcotics dept.",
  "Work from home and earn 5000 daily by liking YouTube videos and completing tasks.",
  "Final notice: Your SIM card will be deactivated in 2 hours for lack of KYC.",
  "Your son has been arrested in a major accident case. Pay bail via UPI immediately.",
  "Income Tax Dept Alert: Your refund of ₹15,400 is approved. Update bank details.",
  "MTNL Alert: Your broadband will be suspended. Pay pending bill of ₹1,200 now.",
  "Urgent: Unrecognized login to your NetBanking from New Delhi. Lock account now."
];

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear, scamLibrary = [], onRunTrial }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isLibraryForcedOpen, setIsLibraryForcedOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const [validationError, setValidationError] = useState<string | null>(null);
  const recognitionRef = useRef<any>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textarea logic
  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.style.height = 'auto';
      inputRef.current.style.height = `${inputRef.current.scrollHeight}px`;
    }
  }, [input]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = 'en-IN';

      recognitionRef.current.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        if (finalTranscript) handleInputChange(input + (input ? ' ' : '') + finalTranscript);
      };

      recognitionRef.current.onend = () => setIsListening(false);
      recognitionRef.current.onerror = () => setIsListening(false);
    }

    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsLibraryForcedOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [input]);

  const validateInput = (val: string): string | null => {
    if (!val) return null;
    const validRegex = /^[a-zA-Z0-9\s.,!?;:()'"\-@#/%&*_=+<>\[\]{}|~`]*$/;
    if (!validRegex.test(val)) {
      return "Illegal characters detected in intake buffer. Only alphanumeric and common punctuation permitted.";
    }
    return null;
  };

  const handleInputChange = (val: string) => {
    setInput(val);
    setValidationError(validateInput(val));

    if (val.length > 1) {
      const filtered = COMMON_SCAM_PHRASES.filter(phrase => 
        phrase.toLowerCase().includes(val.toLowerCase())
      );
      setSuggestions(filtered);
    } else {
      setSuggestions([]);
    }
  };

  const selectSuggestion = (suggestion: string) => {
    handleInputChange(suggestion);
    setIsLibraryForcedOpen(false);
    if (inputRef.current) inputRef.current.focus();
  };

  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) handleInputChange(input + text);
    } catch (err) {
      console.error('Failed to read clipboard', err);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    const isVisible = isLibraryForcedOpen || (input.length > 1 && suggestions.length > 0);
    if (!isVisible) return;

    const currentList = isLibraryForcedOpen && input.length <= 1 ? COMMON_SCAM_PHRASES : suggestions;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedIndex(prev => (prev < currentList.length - 1 ? prev + 1 : prev));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedIndex(prev => (prev > 0 ? prev - 1 : prev));
    } else if (e.key === 'Enter' && focusedIndex >= 0) {
      e.preventDefault();
      selectSuggestion(currentList[focusedIndex]);
    } else if (e.key === 'Escape') {
      setIsLibraryForcedOpen(false);
    }
  };

  const handleAnalyze = async () => {
    if (!input.trim() || validationError) return;
    setLoading(true);
    onAnalysisStart();
    setIsLibraryForcedOpen(false);
    try {
      const result = await analyzeMessage(input, scamLibrary);
      onAnalysisComplete(input, result);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const activeSuggestions = (isLibraryForcedOpen && input.length <= 1) ? COMMON_SCAM_PHRASES : suggestions;
  const showDropdown = isLibraryForcedOpen || (input.length > 1 && suggestions.length > 0);

  return (
    <div className="space-y-8 animate-in slide-in-from-left-4 duration-1000" ref={containerRef}>
      <div className={`bg-[#0f172a]/40 rounded-[3rem] border overflow-hidden relative shadow-2xl backdrop-blur-sm group p-1 ring-1 transition-all duration-500 ${validationError ? 'border-red-500/30 ring-red-500/10' : 'border-blue-500/20 ring-blue-500/10'} ${!input ? 'animate-pulse-soft border-blue-500/40' : ''}`}>
        <div className={`bg-black/80 rounded-[2.8rem] p-6 lg:p-10 space-y-6 lg:space-y-10 transition-colors duration-500 ${validationError ? 'bg-red-950/20' : ''}`}>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
             <div className="space-y-1">
                <h3 className={`text-[10px] font-black uppercase tracking-[0.4em] transition-colors flex items-center ${validationError ? 'text-red-500' : 'text-blue-500'}`}>
                  <div className={`w-2 h-2 rounded-full mr-3 ${validationError ? 'bg-red-500' : 'bg-blue-500 animate-pulse'}`} />
                  {validationError ? 'INTEGRITY_ALERT' : 'READY_FOR_INTAKE'}
                </h3>
                <p className="text-lg font-bold text-white tracking-tight uppercase">Buffered Interception Terminal</p>
                {!input && (
                  <button 
                    onClick={onRunTrial}
                    className="text-[10px] font-black text-blue-400 hover:text-white uppercase tracking-widest mt-2 flex items-center space-x-2 transition-colors"
                  >
                    <span>⚡ Quick Launch: Diagnostic Trial Run</span>
                  </button>
                )}
             </div>
             <div className="flex items-center space-x-4">
                <div className="flex flex-col items-end">
                   <div className={`text-[8px] font-mono font-black uppercase tracking-[0.2em] mb-1 ${validationError ? 'text-red-500' : 'text-slate-600'}`}>
                     System: {validationError ? 'COMPROMISED' : 'NOMINAL_IDLE'}
                   </div>
                   <button 
                     type="button"
                     onClick={() => {
                       setIsLibraryForcedOpen(!isLibraryForcedOpen);
                       setFocusedIndex(-1);
                     }}
                     className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${isLibraryForcedOpen ? 'bg-blue-600 text-white' : 'bg-blue-500/10 border border-blue-500/20 text-blue-500 hover:bg-blue-500/20'}`}
                   >
                     {isLibraryForcedOpen ? 'Close Library' : 'Browse Library'}
                   </button>
                </div>
             </div>
          </div>

          <div className="relative" id="analyzer-input">
             <textarea
               ref={inputRef}
               className={`relative w-full min-h-[12rem] max-h-[32rem] p-6 lg:p-8 bg-black/60 border rounded-[2.5rem] text-white outline-none transition-all resize-none text-base lg:text-xl font-medium placeholder:text-slate-500 leading-relaxed font-mono overflow-y-auto custom-scrollbar ${validationError ? 'border-red-500/40 focus:ring-1 focus:ring-red-500/50' : 'border-white/10 focus:ring-1 focus:ring-blue-500/50 focus:bg-blue-950/20'}`}
               placeholder=">>> PASTE SUSPICIOUS TEXT HERE OR USE MIC..."
               value={input}
               onChange={(e) => handleInputChange(e.target.value)}
               onKeyDown={handleKeyDown}
               style={{ height: 'auto' }}
             />

             {/* Action Overlay */}
             <div className="absolute top-6 right-6 flex flex-col space-y-3">
                <button 
                  onClick={handlePaste}
                  className="w-10 h-10 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl flex items-center justify-center text-slate-400 hover:text-white transition-all group"
                  title="Paste from clipboard"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                </button>
                <button
                  onClick={() => {
                    if (isListening) recognitionRef.current.stop();
                    else { recognitionRef.current.start(); setIsListening(true); }
                  }}
                  className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all duration-500 border ${
                    isListening 
                    ? 'bg-red-600 border-red-400 text-white shadow-[0_0_20px_#ef4444]' 
                    : 'bg-blue-600/10 border-blue-500/30 text-blue-500 hover:bg-blue-600 hover:text-white'
                  }`}
                  title="Voice dictation"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </button>
             </div>

             {validationError && (
               <div className="mt-4 p-4 bg-red-600/10 border border-red-500/30 rounded-2xl flex items-start space-x-3 animate-in slide-in-from-top-2">
                  <svg className="w-4 h-4 text-red-500 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-widest leading-relaxed">{validationError}</p>
               </div>
             )}

             {showDropdown && (
               <div className="absolute left-0 right-0 top-full mt-2 bg-[#0a0f1d] border border-blue-500/40 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.9)] z-[100] overflow-hidden backdrop-blur-3xl animate-in fade-in slide-in-from-top-2">
                 <div className="px-6 py-4 border-b border-white/5 bg-blue-950/20 flex justify-between items-center">
                    <span className="text-[8px] font-black text-blue-400 uppercase tracking-[0.4em] flex items-center">
                       <div className="w-1.5 h-1.5 bg-blue-500 rounded-full mr-2 animate-ping" />
                       Matching Fraud Patterns
                    </span>
                    <span className="text-[8px] font-mono text-slate-500 uppercase">Use ↑↓ Keys to Navigate</span>
                 </div>
                 <div className="max-h-72 overflow-y-auto no-scrollbar py-2">
                   {activeSuggestions.map((phrase, idx) => (
                     <button
                       key={idx}
                       onMouseEnter={() => setFocusedIndex(idx)}
                       onClick={() => selectSuggestion(phrase)}
                       className={`w-full text-left px-8 py-4 text-xs transition-all border-b border-white/5 last:border-0 font-medium flex items-start space-x-4 ${
                         focusedIndex === idx 
                         ? 'bg-blue-600/30 text-white translate-x-1' 
                         : 'text-slate-400 hover:text-slate-200'
                       }`}
                     >
                       <span className="flex-1">{phrase}</span>
                       {focusedIndex === idx && <span className="text-blue-500">↵</span>}
                     </button>
                   ))}
                 </div>
               </div>
             )}
          </div>

          <div className="flex flex-col sm:flex-row gap-4">
            <button
              onClick={handleAnalyze}
              disabled={loading || input.length < 5 || !!validationError}
              className={`flex-1 py-4 lg:py-6 rounded-[1.5rem] lg:rounded-[2rem] font-black text-sm lg:text-lg tracking-[0.2em] shadow-2xl transition-all flex items-center justify-center space-x-4 relative overflow-hidden active:scale-95 ${loading || !!validationError ? 'bg-slate-800 text-slate-500 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
            >
              {loading ? <span className="uppercase tracking-[0.3em] text-xs">Processing Intel...</span> : <span className="uppercase tracking-[0.4em] text-xs">Execute Forensic Scan</span>}
            </button>
            <button
               onClick={() => {handleInputChange(''); onClear(); setIsLibraryForcedOpen(false);}}
               className="px-6 lg:px-10 py-4 lg:py-6 bg-white/5 border border-white/10 rounded-[1.5rem] lg:rounded-[2rem] text-slate-500 hover:text-white hover:bg-white/10 transition-all font-black uppercase text-[10px] lg:text-xs tracking-widest"
            >
              Clear
            </button>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap gap-3">
        {SCAM_SCENARIOS.map((s, idx) => (
          <button 
            key={idx}
            onClick={() => {handleInputChange(s.msg); setIsLibraryForcedOpen(false);}}
