    setTimeout(() => {
      analyzeMessage(trialMessage, scamLibrary).then(result => {
        handleAnalysisComplete(trialMessage, result, true);
        setDiagnosticLog(prev => ["SCAM_CONFIRMED", "NAVIGATING_TO_EVIDENCE_MAP", ...prev]);
        setIsTrialRunning(false);
      });
    }, 1500);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-500/30">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {showSimReport && (
        <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-3xl flex items-center justify-center p-6">
           <div className="max-w-4xl w-full bg-[#0f172a] border border-blue-500/30 rounded-[3rem] p-12 space-y-8 shadow-[0_0_100px_rgba(59,130,246,0.2)] animate-in zoom-in-95 duration-500">
              <div className="flex justify-between items-start">
                 <div className="space-y-2">
                    <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">Sovereign Stress Test Report</h3>
                    <h2 className="text-4xl font-black text-white uppercase tracking-tighter">National Grid Resilience: <span className="text-green-500">NOMINAL</span></h2>
                 </div>
                 <button onClick={() => setShowSimReport(false)} className="text-slate-500 hover:text-white transition-colors">✕</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
