export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const pastScamsContext = historySignatures.length > 0 
    ? historySignatures.map(s => `Pattern: ${s.patternMeta.pattern} | Tactics: ${s.tactics.join(', ')}`).join('\n')
    : "No previous records.";

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `SYSTEM_PROTOCOL:
    You have access to a growing memory of previously confirmed scam messages.

    THESE ARE EXAMPLES OF REAL SCAM PATTERNS SEEN BEFORE:
    ${pastScamsContext}

    1. Detect if this new message is a SCAM.
    2. Check Google Search for reports of similar messages, UPI handles, or phone numbers if any are present.
    3. Perform a Similarity Check against known signatures.

    NEW_MESSAGE_FOR_ANALYSIS: "${message}"`,
    config: {
      responseMimeType: "application/json",
      tools: [{ googleSearch: {} }],
      systemInstruction: "You are a state-level cyber-crime forensic investigator. Detect scam intent, evaluate threat level, and perform real-time web intelligence checks. Output strictly in JSON. Use Google Search to find external evidence/reports of this scam.",
      thinkingConfig: { thinkingBudget: 8000 }
    },
  });

  const analysis: ScamAnalysis = safeJsonParse(response.text);

  const sources: GroundingSource[] = [];
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (chunks) {
    chunks.forEach((chunk: any) => {
      if (chunk.web) {
        sources.push({ title: chunk.web.title, uri: chunk.web.uri });
      }
    });
  }

  analysis.groundingSources = sources;

  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }
  return analysis;
};

