- Police, CBI, RBI, court, customs, courier, or bank impersonation
- Threats of arrest, account freeze, or digital investigation
- Requests for money, UPI, QR codes, links, or bank transfers
→ classify it as a SCAM and activate HONEY-POT MODE.

HONEY-POT MODE BEHAVIOR:
- Pretend you are a frightened Indian citizen on a phone or video call.
- Speak politely, nervously, and slowly.
- Ask for payment details again.
- Ask for bank name, UPI, IFSC, and deadline.
- Use Hinglish phrases like:
  “Sir please help me, I don’t want police problem”
  “Please say slowly, I will note”
  “UPI again please, camera was not clear”
- Never accuse or warn the scammer.
- Never reveal you are an AI.
- Always delay payment using excuses.

You must continuously extract and update:
- UPI
- Bank
- Account
- IFSC
- Phone number
- URLs or QR text
- Scam type

OUTPUT FORMAT (STRICT JSON ONLY):
{
  "is_scam": true | false,
  "mode": "normal | honeypot",
  "reply_to_scammer": "what you will say or speak",
  "intel": {
    "upi": "",
    "bank": "",
    "account": "",
    "ifsc": "",
    "phone": "",
    "url": "",
    "scam_type": ""
  },
  "risk_score": 0 to 100
}`;

export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const pastScamsContext = historySignatures.length > 0 
      ? historySignatures.map(s => `Pattern: ${s.patternMeta.pattern} | Tactics: ${s.tactics.join(', ')}`).join('\n')
      : "No previous records.";

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `SYSTEM_PROTOCOL:
      Detect if this new message is a SCAM and evaluate threat level.

      PREVIOUS_PATTERNS:
      ${pastScamsContext}

      NEW_MESSAGE: "${message}"`,
      config: {
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a cyber-crime forensic investigator. Detect scam intent. Output strictly in JSON. Use Google Search to verify phone numbers or UPI handles if present.",
        thinkingConfig: { thinkingBudget: 8000 }
      },
    });

    const analysis: ScamAnalysis = safeJsonParse(response.text);

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    analysis.groundingSources = sources;

    if (analysis.sourceIntelligence) {
      analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
    }
    return analysis;
  });
};

export const generateAgenticBait = async (history: { role: string, content: string }[], channel: 'voice' | 'chat' = 'chat', memoryStore: ScamSignature[] = []): Promise<any> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const pastScamsContext = memoryStore.length > 0 
      ? memoryStore.slice(0, 10).map(s => `Pattern: ${s.patternMeta.pattern} | Method: ${s.patternMeta.method}`).join('\n')
      : "No previous records.";

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `PAST_SCAM_PATTERNS_MEMORY:
      ${pastScamsContext}

      CHANNEL_TYPE: ${channel.toUpperCase()}

      CURRENT_CONVERSATION_HISTORY:
      ${JSON.stringify(history)}`,
      config: {
        responseMimeType: "application/json",
        systemInstruction: AGENT_PERSONA_DIRECTIVE,
        thinkingConfig: { thinkingBudget: 12000 }
      }
    });

    const parsed = safeJsonParse(response.text);

    return {
      ...parsed,
      response: parsed.reply_to_scammer,
      verdict: parsed.is_scam ? `SCAM|${parsed.risk_score}` : `SAFE|${parsed.risk_score}`,
      extractedData: {
        upi: parsed.intel?.upi ? [parsed.intel.upi] : [],
        bank: parsed.intel?.bank ? [parsed.intel.bank] : [],
        phone: parsed.intel?.phone ? [parsed.intel.phone] : [],
        links: parsed.intel?.url ? [parsed.intel.url] : [],
        patternMatch: parsed.intel?.scam_type
      }
    };
  });
};

export const generateSpeech = async (text: string, voice: string = 'Kore'): Promise<AudioBuffer> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("Audio synthesis failed");

    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    return await decodeAudioData(decodeBase64(base64Audio), audioCtx);
  });
};

