export const generateSyntheticBaitImage = async (prompt: string): Promise<string> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Generate a photorealistic person's ${prompt}. Synthetic bait only.` }]
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:image/png;base64,${imagePart.inlineData.data}`;
    }
    throw new Error("Image generation failed");
  });
};

export const analyzeVideoFrame = async (base64: string): Promise<VideoAnalysis> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64 } },
          { text: "Examine frame for deepfake artifacts." }
        ],
      },
      config: { responseMimeType: "application/json" },
    });
    return safeJsonParse(response.text);
  });
};

export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, extractForensicDossier, generateSpeech, generateSyntheticBaitImage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics, BaitAsset, ForensicDossier } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onForensicFinalized?: (dossier: ForensicDossier) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onForensicFinalized, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [channelMode, setChannelMode] = useState<'voice' | 'chat'>('chat');
  const [activeMode, setActiveMode] = useState<"normal" | "honeypot">("normal");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    if (isTyping) return; // Prevent concurrent requests
    setIsTyping(true);
    setError(null);

    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history, channelMode);

      setActiveMode(result.mode || "normal");

      // We only store and show the human-like reply from the agent
      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.reply_to_scammer, 
        timestamp: Date.now(),
        verdict: result.verdict,
        extractedData: result.extractedData
      }];

      onMessagesUpdate(updatedMessages);

      if (result.intel) {
        const info: ExtractedInfo = {
          upiIds: result.intel.upi ? [{ value: result.intel.upi, confidence: 95, timestamp: Date.now() }] : [],
          bankDetails: result.intel.bank ? [{ value: result.intel.bank, confidence: 95, timestamp: Date.now() }] : [],
          ifscCodes: result.intel.ifsc ? [{ value: result.intel.ifsc, confidence: 95, timestamp: Date.now() }] : [],
          phoneNumbers: result.intel.phone ? [{ value: result.intel.phone, confidence: 95, timestamp: Date.now() }] : [],
          links: result.intel.url ? [{ value: result.intel.url, confidence: 95, timestamp: Date.now() }] : [],
          cryptoWallets: [],
          fakeIdentities: []
        };
        onIntelExtracted(info);
      }

    } catch (e: any) {
      console.error(e);
      // Check if it's a quota error or a general logic confusion
      if (e.message?.includes('429') || e.message?.includes('quota')) {
        setError("GRID_QUOTA_EXHAUSTED: Please check API Billing or slow down interactions.");
      } else {
        // Hardcoded persona failsafe for general errors
        setError("Sir please explain again, I am little confused.");
      }
    } finally {
      setIsTyping(false);
    }
  };

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTyping) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);
    setTimeout(() => runAgenticTurn(updatedMessages), 100);
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  return (
    <div className="glass-panel rounded-[3.5rem] border border-white/10 flex flex-col h-full overflow-hidden relative shadow-2xl">
      <div className="p-8 bg-black/70 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl z-20">
        <div className="flex items-center space-x-6">
          <div className="relative">
            <div className={`w-14 h-14 rounded-2xl border flex items-center justify-center transition-all duration-500 ${activeMode === 'honeypot' ? 'bg-orange-600/10 border-orange-500/30 shadow-[0_0_30px_rgba(249,115,22,0.1)]' : 'bg-blue-600/10 border-blue-500/30'}`}>
               <svg className={`w-7 h-7 ${activeMode === 'honeypot' ? 'text-orange-500' : 'text-blue-500'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
               </svg>
            </div>
            {activeMode === 'honeypot' && (
              <div className="absolute -top-1 -right-1 w-4 h-4 bg-orange-500 rounded-full border-2 border-black animate-ping" />
            )}
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.4em] flex items-center">
              Agent Deployment
              <span className={`ml-4 text-[8px] font-black ${activeMode === 'honeypot' ? 'text-orange-500 bg-orange-500/10 border-orange-500/20' : 'text-blue-500 bg-blue-500/10 border-blue-500/20'} px-2 py-0.5 rounded-full border uppercase tracking-widest`}>
                {activeMode === 'honeypot' ? 'Honey-Pot: Frightened Citizen' : 'Persona: Direct Analysis'}
              </span>
            </h3>
            <div className="mt-1 flex items-center space-x-2">
               <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 font-mono">
                 Channel: <span className="text-blue-400">{channelMode.toUpperCase()} MODE</span>
               </span>
               <div className="w-1 h-1 bg-slate-700 rounded-full" />
               <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 font-mono">
                 Speech: <span className={activeMode === 'honeypot' ? 'text-orange-400' : 'text-green-500'}>{activeMode === 'honeypot' ? 'NERVOUS_SLOW' : 'OPTIMAL'}</span>
               </span>
            </div>
          </div>
        </div>

        <div className="flex bg-white/5 rounded-xl p-1 border border-white/10 shadow-inner">
          <button 
            onClick={() => setChannelMode('chat')} 
            className={`px-6 py-2 rounded-lg text-[9px] font-black uppercase tracking-[0.2em] transition-all ${channelMode === 'chat' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Chat
          </button>
          <button 
            onClick={() => setChannelMode('voice')} 
            className={`px-6 py-2 rounded-lg text-[9px] font-black uppercase tracking-[0.2em] transition-all ${channelMode === 'voice' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Voice
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0f172a_0%,_#020617_100%)]">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-12 no-scrollbar custom-scrollbar">
          {initialMessages.map((m, idx) => (
            <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'} animate-in slide-in-from-bottom-4 duration-500`}>
              <div className={`text-[8px] font-black uppercase tracking-widest mb-3 ${m.role === 'scammer' ? 'text-slate-500' : 'text-blue-500'}`}>
                {m.role === 'scammer' ? 'Inbound Intercept' : (activeMode === 'honeypot' ? 'Citizen Decoy (Frightened)' : 'Agent Output')}
              </div>
              <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-[15px] leading-relaxed relative group shadow-2xl ${
                m.role === 'scammer' ? 'bg-slate-900 text-slate-100 border border-white/10 rounded-bl-none' 
                : (activeMode === 'honeypot' ? 'bg-orange-600 text-white border border-orange-400/30 rounded-br-none shadow-[0_10px_30px_rgba(234,88,12,0.2)] italic' : 'bg-blue-600 text-white border border-blue-400/30 rounded-br-none')
              }`}>
                {m.content}

                {m.role === 'bot' && (
                  <div className="absolute -bottom-6 right-0 text-[8px] font-mono text-slate-600 uppercase tracking-widest">
                    Modulation: {channelMode === 'voice' ? (activeMode === 'honeypot' ? 'Nervous-Polite-Slow' : 'Neural-Hinglish-Synth') : 'Strict-Plain-Text'}
                  </div>
                )}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex flex-col items-end space-y-4">
               <div className="flex items-center space-x-3">
                 <div className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-500 animate-pulse">
                   {activeMode === 'honeypot' ? 'SYNTHESIZING FRIGHTENED RESPONSE' : 'Agent Synchronizing Persona'}
                 </div>
                 <div className="flex space-x-1">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" />
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]" />
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]" />
                 </div>
               </div>
            </div>
          )}
          {error && (
            <div className="flex flex-col items-end">
              <div className={`max-w-[85%] ${error.includes('QUOTA') ? 'bg-red-600' : 'bg-orange-600'} text-white border border-white/30 rounded-[2rem] rounded-br-none px-8 py-5 text-[15px] leading-relaxed shadow-2xl`}>
                 {error}
              </div>
              <div className={`mt-2 text-[8px] font-black ${error.includes('QUOTA') ? 'text-red-500' : 'text-orange-500'} uppercase tracking-widest`}>
                {error.includes('QUOTA') ? 'Resource Exhaustion Detected' : 'Failsafe: Auto-Confusion Protocol Triggered'}
              </div>
            </div>
          )}
        </div>

        <div className="p-10 bg-black/80 border-t border-white/5 backdrop-blur-3xl">
          <form onSubmit={(e) => {
            e.preventDefault();
            const target = e.target as any;
            handleManualScammerReply(target.reply.value);
            target.reply.value = '';
          }} className="flex space-x-6">
            <div className="flex-1 relative">
              <input 
                name="reply"
                disabled={isTyping}
                autoComplete="off"
                placeholder={isTyping ? ">>> AGENT IS RESPONDING..." : ">>> INPUT SCAMMER MESSAGE TO ENGAGE"}
                className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-5 text-sm text-white outline-none focus:ring-1 focus:ring-blue-600 font-mono transition-all placeholder:text-slate-700"
              />
              <div className="absolute right-6 top-1/2 -translate-y-1/2 text-[10px] font-mono text-slate-800">
                UTF-8 // RAW
              </div>
            </div>
            <button 
              type="submit" 
              disabled={isTyping} 
              className="bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 px-10 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.3em] transition-all shadow-xl active:scale-95"
            >
              Send
            </button>
          </form>
          <div className="mt-4 flex justify-between items-center px-4">
            <div className="text-[8px] font-black text-slate-600 uppercase tracking-widest">
              Security Notice: You are simulating a live scammer interaction for intelligence siphoning.
            </div>
            <div className="flex space-x-4">
              <span className="text-[8px] font-black text-blue-500 uppercase">E2EE_Active</span>
              <span className="text-[8px] font-black text-slate-700 uppercase">Sovereign_OS v4.1</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

