export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Detect scam intent and extract initial data: "${message}"`,
      config: {
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a cyber-crime forensic investigator. Detect scam intent. Output JSON.",
        thinkingConfig: { thinkingBudget: 8000 }
      },
    });

    const analysis: ScamAnalysis = safeJsonParse(response.text);

    // Guardian & Hub initial drafts
    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
      analysis.operationalReport = await generateOperationalReport(analysis);
    }

    return analysis;
  });
};

export const generateGuardianGuidance = async (analysis: ScamAnalysis): Promise<GuardianGuidance> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `SCAM_INTEL: ${JSON.stringify(analysis)}`,
      config: {
        responseMimeType: "application/json",
        systemInstruction: GUARDIAN_PERSONA_DIRECTIVE,
      }
    });
    return safeJsonParse(response.text);
  });
};

