        <div className="fixed top-0 left-0 w-full h-1 bg-blue-900 z-[100]">
          <div className="h-full bg-blue-500 shadow-[0_0_20px_#3b82f6] transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {showSimReport && (
        <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-3xl flex items-center justify-center p-6">
           <div className="max-w-4xl w-full bg-[#0f172a] border border-blue-500/30 rounded-[3rem] p-12 space-y-8 shadow-[0_0_100px_rgba(59,130,246,0.2)] animate-in zoom-in-95 duration-500">
              <div className="flex justify-between items-start">
                 <div className="space-y-2">
                    <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">Sovereign Stress Test Report</h3>
                    <h2 className="text-4xl font-black text-white uppercase tracking-tighter">National Grid Resilience: <span className="text-green-500">NOMINAL</span></h2>
                 </div>
                 <button onClick={() => setShowSimReport(false)} className="text-slate-500 hover:text-white transition-colors">✕</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <ReportMetric label="Total Interceptions" value="5,000" sub="All Nodes Responding" />
                 <ReportMetric label="Prevention Value" value={`₹${(logs.reduce((s, l) => s + (l.estimatedImpact || 0), 0) / 10000000).toFixed(2)} Cr`} sub="Institutional Savings" />
                 <ReportMetric label="Extraction Rate" value="94.2%" sub="IoCs Siphoned Successfully" />
              </div>

              <div className="bg-black/40 border border-white/5 p-8 rounded-3xl space-y-4">
                 <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Multi-Channel Distribution</h4>
                 <div className="flex items-end h-24 space-x-4">
                    <ChannelBar label="SMS" percent={35} color="bg-blue-500" />
                    <ChannelBar label="WhatsApp" percent={28} color="bg-green-500" />
                    <ChannelBar label="Voice" percent={22} color="bg-orange-500" />
                    <ChannelBar label="Video" percent={15} color="bg-red-500" />
                 </div>
              </div>

              <div className="flex justify-center pt-6">
                 <button onClick={() => setShowSimReport(false)} className="px-12 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest transition-all glow-cobalt">Close Report</button>
              </div>
           </div>
        </div>
      )}

      {showTutorial && (
        <OnboardingTour activeView={view} onViewChange={(v) => setView(v)} onComplete={() => setShowTutorial(false)} />
      )}

      {showTutor && (
        <RakshakTutor onClose={() => setShowTutor(false)} />
      )}

      {/* Floating Tutor Toggle Button */}
      <button 
        onClick={() => setShowTutor(!showTutor)}
        className="fixed bottom-8 left-8 z-[150] w-14 h-14 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl shadow-2xl hover:bg-blue-500 hover:scale-110 transition-all active:scale-95 group"
      >
        <span className="group-hover:animate-bounce">🧑‍🏫</span>
        <div className="absolute -top-12 left-0 bg-blue-600 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">Rakshak Mitra</div>
      </button>

      <header className="glass-panel px-4 lg:px-10 py-4 lg:py-6 flex flex-wrap items-center justify-between sticky top-0 z-[60] border-b border-white/10 gap-4">
        <div className="flex items-center space-x-3 lg:space-x-6">
          <div className="bg-blue-600 p-2 lg:p-3 rounded-xl lg:rounded-2xl shadow-[0_0_25px_rgba(37,99,235,0.4)] glow-cobalt shrink-0">
            <svg className="w-5 h-5 lg:w-6 lg:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('analyzer'); setLatestAnalysis(null);}} className="text-left group">
            <h1 className="text-lg lg:text-2xl font-black tracking-tighter text-white uppercase group-hover:text-blue-400 transition-colors">BHARAT CYBER <span className="text-blue-500">RAKSHAK</span></h1>
            <p className="text-[7px] lg:text-[9px] text-slate-500 font-black uppercase tracking-[0.5em] font-mono">SOVEREIGN_AGENT_GRID_v2.5</p>
          </button>
        </div>

        <nav className="hidden xl:flex items-center space-x-2 bg-white/5 p-1.5 rounded-2xl border border-white/10">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Containment" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Map" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia Intel" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="Sovereign War Room" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Dossiers" />
        </nav>

        <div className="flex items-center space-x-3 lg:space-x-8">
           <button onClick={() => runSimulation(5000)} className="bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white px-4 py-2 rounded-xl border border-red-500/20 transition-all text-[9px] font-black uppercase tracking-widest">
              Stress Test
           </button>
           <button onClick={() => setShowTutorial(true)} className="flex items-center space-x-2 bg-white/5 hover:bg-white/10 px-3 lg:px-4 py-2 rounded-lg lg:rounded-xl border border-white/10 transition-all group">
              <svg className="w-3.5 h-3.5 lg:w-4 lg:h-4 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              <span className="text-[8px] lg:text-[10px] font-black text-slate-300 uppercase tracking-widest">Tutorial</span>
           </button>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'warroom' ? (
          <WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} onOpenKey={() => {}} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : view === 'multimedia' ? (
          <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <VoiceSynthesisLab />
                <VideoScanner />
             </div>
          </div>
        ) : (
          <div className="space-y-16">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start pt-8">
              <div className="lg:col-span-7 space-y-10">
                <h2 className="text-4xl lg:text-6xl font-black text-white tracking-tighter uppercase leading-none">
                  ADAPTIVE <span className="text-blue-500">DEFENSE</span> INTERFACE
                </h2>
                <ScamAnalyzer 
                   onAnalysisComplete={(msg) => handleManualAnalyze(msg)} 
                   onAnalysisStart={() => {}} 
                   onClear={() => setLatestAnalysis(null)} 
                   scamLibrary={scamLibrary}
                />
              </div>
            </div>

            {latestAnalysis && (
              <div id="results-anchor" className="space-y-24 animate-in slide-in-from-bottom-20 duration-1000 pt-16 border-t border-white/5">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[900px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                      onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                      onOperationalReportGenerated={(report) => updateOperationalReport(latestAnalysis.sessionId, report)}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

const ReportMetric = ({ label, value, sub }: any) => (
  <div className="bg-white/5 border border-white/5 p-6 rounded-2xl space-y-2">
    <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label}</div>
    <div className="text-3xl font-black text-white">{value}</div>
    <div className="text-[9px] font-bold text-blue-500 uppercase tracking-tighter">{sub}</div>
  </div>
);

const ChannelBar = ({ label, percent, color }: any) => (
  <div className="flex-1 flex flex-col items-center space-y-2">
    <div className="text-[9px] font-black text-white">{percent}%</div>
    <div className={`w-full rounded-t-lg ${color}`} style={{ height: `${percent * 2}%` }} />
    <div className="text-[8px] font-black text-slate-500 uppercase">{label}</div>
  </div>
);

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${active ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
    {label}
  </button>
);

export default App;
